function getPackCatalogWorkflowPreflightReadiness(catalog, { includeAll = false } = {}) {
  const manifest = buildPlanPackBundleManifest(catalog, { includeAll });
  const schemaIndexCoverage = manifest.schemaIndexContractCoverage || buildPlanPackBundleSchemasIndexJson(manifest).contractCoverageSummary || {};
  const schemaCount = Number(schemaIndexCoverage.workflowPreflightSchemaCount || 0);
  const commandCount = Number(schemaIndexCoverage.workflowPreflightCommandCount || 0);
  const sourceCount = Number(schemaIndexCoverage.workflowPreflightSourceCount || 0);
  const missingCommandSchemaIds = Array.isArray(schemaIndexCoverage.missingWorkflowPreflightCommandSchemaIds) ? schemaIndexCoverage.missingWorkflowPreflightCommandSchemaIds : [];
  const missingSourceSchemaIds = Array.isArray(schemaIndexCoverage.missingWorkflowPreflightSourceSchemaIds) ? schemaIndexCoverage.missingWorkflowPreflightSourceSchemaIds : [];
  const ready = schemaCount > 0
    && commandCount >= schemaCount
    && sourceCount >= schemaCount
    && missingCommandSchemaIds.length === 0
    && missingSourceSchemaIds.length === 0;
  return {
    status: ready ? "met" : "breached",
    ok: ready ? "yes" : "no",
    schemaCount,
    commandCount,
    sourceCount,
    missingCommandSchemaIds,
    missingSourceSchemaIds,
    recommendedAction: ready ? "Workflow preflight metadata is ready." : "Review Workflow preflight command/source metadata in Schema Index before wiring automated handoff consumers.",
  };
}

