  const packCatalogCsvSchemaPath = includeAll ? catalog.exports?.csvSchemaAllPath : catalog.exports?.csvSchemaPath;
  const packCatalogCsvSchemaUrl = includeAll ? catalog.exports?.csvSchemaAllUrl : catalog.exports?.csvSchemaUrl;
  const workflowPreflightMode = includeAll ? catalog.exports?.bundleWorkflowPreflightCommandMode : catalog.exports?.bundleDisplayWorkflowPreflightCommandMode || catalog.exports?.bundleWorkflowPreflightCommandMode;
  const workflowPreflightJsonPath = includeAll ? catalog.exports?.bundleWorkflowPreflightJsonAllPath : catalog.exports?.bundleDisplayWorkflowPreflightJsonPath || catalog.exports?.bundleWorkflowPreflightJsonPath;
