function buildPlanPackMarkdownById(plan, packId, { baseUrl = "", generatedAt = new Date().toISOString() } = {}) {
  const webUrl = baseUrl ? new URL(`/plans/${plan.id}`, baseUrl).toString() : "";
  switch (packId) {
    case "file-guide":
      return buildFileGuideMarkdown(plan, { generatedAt, webUrl });
    case "offline-pack":
      return buildOfflinePackMarkdown(plan, { exportedAt: generatedAt, webUrl });
    case "departure-pack":
      return buildDeparturePackMarkdown(plan);
    case "today-pack":
      return buildTodayPackMarkdown(plan);
    case "safety-pack":
      return buildSafetyPackMarkdown(plan);
    case "share-pack":
      return buildSharePackMarkdown(plan);
    case "money-pack":
      return buildMoneyPackMarkdown(plan);
    case "settlement-pack":
      return buildSettlementPackMarkdown(plan);
    case "full-pack":
      return buildFullPackMarkdown(plan);
    case "memo-pack":
      return buildMemoPackMarkdown(plan);
    default:
      return "";
  }
}

function packCatalogDisplayPacks(catalog, { includeAll = false } = {}) {
  if (Array.isArray(catalog.selectedPackIds)) return catalog.packs || [];
  const recommended = (catalog.packs || [])
    .filter((pack) => pack.recommended)
    .sort((a, b) => (a.recommendedOrder || 999) - (b.recommendedOrder || 999));
  return includeAll ? catalog.packs || [] : recommended.length ? recommended : catalog.packs || [];
}

function packCatalogIdsFromQuery(query = {}) {
  return String(query.ids || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

function selectPlanPackCatalogByIds(catalog, ids = []) {
  if (!ids.length) return catalog;
  const packById = new Map((catalog.packs || []).map((pack) => [pack.id, pack]));
  const packs = ids.map((id) => packById.get(id)).filter(Boolean);
  return {
    ...catalog,
    selectedPackIds: packs.map((pack) => pack.id),
    filteredPackCount: packs.length,
    recommendedPackCount: packs.filter((pack) => pack.recommended).length,
    packs,
    recommendedPackIds: packs.filter((pack) => pack.recommended).map((pack) => pack.id),
    primaryPack: pickPrimaryPack(packs),
  };
}

function buildPlanPackBundleMarkdown(plan, catalog, { includeAll = false, scope = "" } = {}) {
  const packs = packCatalogDisplayPacks(catalog, { includeAll });
  const generatedAt = catalog.generatedAt || new Date().toISOString();
  const baseUrl = catalog.exports?.baseUrl || "";
  const filterSummary = packCatalogFilterSummary(catalog);
  const scopeLabel = scope === "selected" ? `선택 ${packs.length}개` : includeAll ? `전체 ${packs.length}개` : `표시 ${packs.length}개`;
  const manifest = buildPlanPackBundleManifest(catalog, { includeAll, scope });
  const schemaIndexCoverage = manifest.schemaIndexContractCoverage || buildPlanPackBundleSchemasIndexJson(manifest).contractCoverageSummary || {};
  const workflowPreflightSchemaCount = Number(schemaIndexCoverage.workflowPreflightSchemaCount || 0);
  const workflowPreflightCommandCount = Number(schemaIndexCoverage.workflowPreflightCommandCount || 0);
  const workflowPreflightSourceCount = Number(schemaIndexCoverage.workflowPreflightSourceCount || 0);
  const missingWorkflowPreflightCommandSchemaIds = Array.isArray(schemaIndexCoverage.missingWorkflowPreflightCommandSchemaIds) ? schemaIndexCoverage.missingWorkflowPreflightCommandSchemaIds : [];
  const missingWorkflowPreflightSourceSchemaIds = Array.isArray(schemaIndexCoverage.missingWorkflowPreflightSourceSchemaIds) ? schemaIndexCoverage.missingWorkflowPreflightSourceSchemaIds : [];
  const workflowPreflightReady = workflowPreflightSchemaCount > 0
    && workflowPreflightCommandCount >= workflowPreflightSchemaCount
    && workflowPreflightSourceCount >= workflowPreflightSchemaCount
    && missingWorkflowPreflightCommandSchemaIds.length === 0
    && missingWorkflowPreflightSourceSchemaIds.length === 0;
  return [
    `# 플랜 #${catalog.planId} v${catalog.latestVersion || 1} Markdown 팩 묶음`,
    "",
    `- 생성 시각: ${generatedAt}`,
    `- 필터: ${filterSummary}`,
    `- 범위: ${scopeLabel}`,
    `- 포함 팩: ${packs.length}개`,
    "",
    "## Workflow preflight readiness",
    "",
    `- status: ${workflowPreflightReady ? "met" : "breached"}`,
    `- ok: ${workflowPreflightReady ? "yes" : "no"}`,
    `- schema count: ${workflowPreflightSchemaCount}`,
    `- command count: ${workflowPreflightCommandCount}`,
    `- source count: ${workflowPreflightSourceCount}`,
    `- missing command schema ids: ${missingWorkflowPreflightCommandSchemaIds.length ? missingWorkflowPreflightCommandSchemaIds.join(", ") : "none"}`,
    `- missing source schema ids: ${missingWorkflowPreflightSourceSchemaIds.length ? missingWorkflowPreflightSourceSchemaIds.join(", ") : "none"}`,
    `- recommended action: ${workflowPreflightReady ? "Workflow preflight metadata is ready." : "Review Workflow preflight command/source metadata in Schema Index before wiring automated handoff consumers."}`,
    "",
    ...packs.map((pack, index) => [
      `<!-- ${index + 1}. ${pack.label || pack.id} -->`,
      buildPlanPackMarkdownById(plan, pack.id, { baseUrl, generatedAt }).trim(),
    ].filter(Boolean).join("\n\n")),
  ].join("\n") + "\n";
}

function pickPrimaryPack(packs = []) {
  const recommended = (packs || [])
    .filter((pack) => pack.recommended)
    .sort((a, b) => (a.recommendedOrder || 999) - (b.recommendedOrder || 999));
  return recommended[0] || (packs || [])[0] || null;
}

function csvCell(value) {
  const text = String(value == null ? "" : value);
  return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

function packCatalogFilterSummary(catalog) {
  const filters = catalog.filters || {};
  const parts = [
    filters.category ? `category=${filters.category}` : "",
    filters.audience ? `audience=${filters.audience}` : "",
    filters.recommended !== null && filters.recommended !== undefined ? `recommended=${filters.recommended}` : "",
  ].filter(Boolean);
  return parts.length ? parts.join(", ") : "없음";
}

function safePackCatalogFilenamePart(value) {
  const slug = String(value == null ? "" : value)
    .trim()
    .toLowerCase()
    .replace(/[^\p{Letter}\p{Number}_-]+/gu, "-")
    .replace(/^-+|-+$/g, "");
  return slug || "filter";
}

function packCatalogFilenameSuffix(catalog, { includeAll = false } = {}) {
  const filters = catalog.filters || {};
  const parts = [
    filters.category ? `category-${safePackCatalogFilenamePart(filters.category)}` : "",
    filters.audience ? `audience-${safePackCatalogFilenamePart(filters.audience)}` : "",
    filters.recommended !== null && filters.recommended !== undefined ? `recommended-${filters.recommended ? "true" : "false"}` : "",
    includeAll ? "all" : "",
  ].filter(Boolean);
  return parts.length ? `-${parts.join("-")}` : "";
}

