function packCatalogFilterFromQuery(query = {}) {
  const recommendedRaw = String(query.recommended || "").trim().toLowerCase();
  return {
    category: String(query.category || "").trim().toLowerCase(),
    audience: String(query.audience || "").trim(),
    recommended: ["1", "true", "yes", "on"].includes(recommendedRaw)
      ? true
      : ["0", "false", "no", "off"].includes(recommendedRaw)
        ? false
        : null,
  };
}

function filterPlanPackCatalog(catalog, filter = {}) {
  const hasFilter = Boolean(filter.category || filter.audience || (filter.recommended !== null && filter.recommended !== undefined));
  if (!hasFilter) return catalog;
  const packs = (catalog.packs || []).filter((pack) => {
    if (filter.category && String(pack.category || "").toLowerCase() !== filter.category) return false;
    if (filter.audience && !String(pack.audience || "").includes(filter.audience)) return false;
    if (filter.recommended !== null && Boolean(pack.recommended) !== filter.recommended) return false;
    return true;
  });
  return withPackCatalogBundleExamples({
    ...catalog,
    filters: filter,
    filteredPackCount: packs.length,
    recommendedPackCount: packs.filter((pack) => pack.recommended).length,
    packs,
    recommendedPackIds: packs.filter((pack) => pack.recommended).map((pack) => pack.id),
    primaryPack: pickPrimaryPack(packs),
    exports: buildPackCatalogExports(catalog.exports?.basePath || `/api/plans/${catalog.planId}`, catalog.exports?.baseUrl || "", filter),
  }, filter);
}

function readNonNegativeInt(value, fallback) {
  if (value === undefined || value === "") return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 ? Math.floor(parsed) : fallback;
}

function getLanUrls() {
  return Object.values(os.networkInterfaces())
    .flat()
    .filter((item) => item && item.family === "IPv4" && !item.internal)
    .map((item) => `http://${item.address}:${PORT}`);
}

function llmStatusDetails() {
  return {
    llmProvider: process.env.LLM_PROVIDER || "auto",
    llmDefaultModels: {
      anthropic: process.env.CLAUDE_MODEL || process.env.LLM_MODEL || "claude-3-haiku-20240307",
      openai: process.env.LLM_MODEL || "gpt-4o-mini",
    },
  };
}

function extractLlmOptions(input = {}) {
  const provider = String(input.llmProvider || "").trim().toLowerCase();
  const apiKey = String(input.llmApiKey || "").trim();
  const model = String(input.llmModel || "").trim();
  if (!apiKey) return null;
  return {
    provider: provider === "server" ? "" : provider,
    apiKey,
    model,
  };
}

function clearRequestLlmApiKey(input = {}) {
  if (Object.prototype.hasOwnProperty.call(input, "llmApiKey")) {
    input.llmApiKey = "";
  }
}

function attachLlmAudit(generation, llmOptions = null) {
  generation.llmAuthMode = llmOptions?.apiKey ? "user-api-key" : "server-default";
  generation.llmProvider = llmOptions?.provider || process.env.LLM_PROVIDER || "auto";
  generation.llmModelOverride = Boolean(llmOptions?.model);
  return generation;
}

function llmOptionsError(llmOptions = null) {
  if (!llmOptions?.apiKey) return "";
  if (["anthropic", "claude", "codex", "openai"].includes(llmOptions.provider)) return "";
  return "llm provider required";
}

function preventSensitiveLlmCaching(res, llmOptions = null) {
  if (llmOptions?.apiKey) {
    res.setHeader("Cache-Control", "no-store");
  }
}

function sweepApiRequestCounts(now) {
  if (now - lastRateLimitSweepAt < API_RATE_LIMIT_WINDOW_MS) return;
  lastRateLimitSweepAt = now;
  for (const [client, entry] of apiRequestCounts) {
    if (now - entry.startedAt >= API_RATE_LIMIT_WINDOW_MS) {
      apiRequestCounts.delete(client);
    }
  }
}

function limitApiRequests(req, res, next) {
  if (!API_RATE_LIMIT_MAX || req.path === "/health" || req.path === "/health.txt" || req.path === "/status") {
    next();
    return;
  }

  const now = Date.now();
  sweepApiRequestCounts(now);
  const client = req.ip || req.socket?.remoteAddress || "unknown";
  const current = apiRequestCounts.get(client);

  if (!current || now - current.startedAt >= API_RATE_LIMIT_WINDOW_MS) {
    apiRequestCounts.set(client, { count: 1, startedAt: now });
    next();
    return;
  }

  if (current.count >= API_RATE_LIMIT_MAX) {
    const retryAfter = Math.ceil((API_RATE_LIMIT_WINDOW_MS - (now - current.startedAt)) / 1000);
    res.setHeader("Retry-After", String(Math.max(1, retryAfter)));
    res.status(429).json({ error: "rate limit exceeded" });
    return;
  }

  current.count += 1;
  next();
}

