function qualityTodoBaseUrl(req) {
  const configured = String(process.env.TRAVEL_PUBLIC_BASE_URL || process.env.PUBLIC_BASE_URL || "").trim();
  if (configured) return configured;
  const host = req.get("host");
  if (!host) return "";
  const protocol = String(req.get("x-forwarded-proto") || req.protocol || "http").split(",")[0].trim();
  return `${protocol}://${host}`;
}

function qualityTodoBaseUrlSource(req) {
  if (String(process.env.TRAVEL_PUBLIC_BASE_URL || "").trim()) return "env-travel";
  if (String(process.env.PUBLIC_BASE_URL || "").trim()) return "env-public";
  if (req.get("host")) return "request-host";
  return "none";
}

function qualityTodoOffset(value) {
  const requested = Number(value || 0);
  return Number.isFinite(requested) ? Math.max(0, Math.min(5000, Math.floor(requested))) : 0;
}

function qualityTodoAll(value) {
  return ["1", "true", "yes", "all"].includes(String(value || "").trim().toLowerCase());
}

function qualityTodoUrgent(value) {
  return ["1", "true", "yes", "urgent"].includes(String(value || "").trim().toLowerCase());
}

function qualityTodoNext(value) {
  return ["1", "true", "yes", "next"].includes(String(value || "").trim().toLowerCase());
}

function qualityTodoFlag(value) {
  return ["1", "true", "yes", "on"].includes(String(value || "").trim().toLowerCase());
}

function qualityTodoMinPriority(value) {
  const requested = Number(value || 0);
  return Number.isFinite(requested) ? Math.max(0, Math.min(100, Math.floor(requested))) : 0;
}

function qualityTodoMaxActions(value) {
  const requested = Number(value);
  return Number.isFinite(requested) ? Math.max(0, Math.min(5000, Math.floor(requested))) : null;
}

async function buildQualityTodoResponse(req, defaults = {}) {
  const requestedLimit = Number(req.query.limit ?? defaults.limit ?? 10);
  const offset = qualityTodoOffset(req.query.offset ?? defaults.offset);
  const all = qualityTodoAll(req.query.all ?? defaults.all);
  const urgent = qualityTodoUrgent(req.query.urgent ?? defaults.urgent);
  const next = qualityTodoNext(req.query.next ?? defaults.next);
  const failOnEmpty = qualityTodoFlag(req.query.failOnEmpty ?? req.query.fail_on_empty ?? defaults.failOnEmpty);
  const maxActions = qualityTodoMaxActions(req.query.maxActions ?? req.query.max_actions);
  const failOnAction = qualityTodoFlag(req.query.failOnAction ?? req.query.fail_on_action ?? defaults.failOnAction) || maxActions !== null;
  const summary = await getPlanQualitySummary(DB_PATH);
  const selectedFilter = next ? String(summary.qualityNextFilter || "quality-action").trim() || "quality-action" : "quality-action";
  const listFilter = selectedFilter === "quality-urgent" ? "quality-action" : selectedFilter;
  const minPriority = qualityTodoMinPriority(req.query.minPriority ?? req.query.min_priority ?? (urgent || selectedFilter === "quality-urgent" ? 80 : 0));
  const scanActionCount = qualityTodoFilterCount(summary, listFilter);
  const baseLimit = Number.isFinite(requestedLimit)
    ? Math.max(1, Math.min(50, Math.floor(requestedLimit)))
    : 10;
  const scanLimit = all || minPriority > 0 ? Math.max(1, Math.min(5000, scanActionCount)) : offset + baseLimit;
  const plans = await listPlans(scanLimit, DB_PATH, listFilter);
  const eligiblePlans = minPriority > 0 ? plans.filter((plan) => Number(plan.qualityActionPriority || 0) >= minPriority) : plans;
  const eligibleActionCount = minPriority > 0 ? eligiblePlans.length : qualityTodoFilterCount(summary, selectedFilter);
  const limit = all
    ? Math.max(1, Math.min(5000, eligibleActionCount - offset))
    : baseLimit;
  const filterLabel = next ? `다음 품질 필터: ${qualityTodoFilterLabel(summary, selectedFilter)}` : "";
  return buildQualityTodoPayload(summary, eligiblePlans.slice(offset, offset + limit), { baseUrl: qualityTodoBaseUrl(req), baseUrlSource: qualityTodoBaseUrlSource(req), limit, offset, source: "api", all, urgent: urgent || selectedFilter === "quality-urgent", next, filter: next ? selectedFilter : "", filterLabel, minPriority, totalActionCount: eligibleActionCount, failOnEmpty, failOnAction, maxActions });
}

