function buildPlanPackBundleCommandPresetMarkdownLines(commandPresets = [], heading = "## 권장 워크플로우") {
  const presets = Array.isArray(commandPresets) ? commandPresets : [];
  if (!presets.length) return [];
  const lines = [heading, ""];
  presets.forEach((preset) => {
    const order = Number.isFinite(preset.order) ? preset.order : "-";
    const verificationModes = Array.isArray(preset.verificationModes) && preset.verificationModes.length
      ? preset.verificationModes.join(", ")
      : "-";
    lines.push("### " + order + ". " + (preset.label || preset.id || "Workflow"));
    lines.push("- Phase: " + (preset.phase || "-"));
    lines.push("- Audience: " + (preset.audience || "-"));
    lines.push("- Recommended: " + (preset.recommended ? "yes" : "no"));
    lines.push("- Primary mode: " + (preset.primaryMode || preset.primaryKey || "-"));
    lines.push("- Verification modes: " + verificationModes);
    lines.push("- Steps: " + (preset.stepCount || (Array.isArray(preset.steps) ? preset.steps.length : 0)));
    lines.push("- Success criteria: " + (preset.successCriteria || "-"));
    lines.push("");
  });
  return lines;
}

