function buildPlanPackBundleCsvSchemaJson(manifest, options = {}) {
  const columns = Array.isArray(options.columns) ? options.columns : [];
  const csvArtifact = getPlanPackBundleArtifactById(manifest, options.csvArtifactId);
  const schemaArtifact = getPlanPackBundleArtifactById(manifest, options.schemaArtifactId);
  const propertyForColumn = (column) => {
    const property = { type: column.type === "integer" ? ["integer", "string"] : "string", description: column.description || "" };
    if (column.enum) property.enum = column.enum;
    return property;
  };
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    title: options.title || "CSV Row",
    description: options.description || "",
    type: "object",
    additionalProperties: false,
    required: columns.map((column) => column.name),
    properties: Object.fromEntries(columns.map((column) => [column.name, propertyForColumn(column)])),
    csv: {
      artifactId: options.csvArtifactId || "",
      path: csvArtifact.path || options.csvPath || "",
      url: csvArtifact.url || options.csvUrl || "",
      filename: csvArtifact.filename || options.csvFilename || "",
      contentType: "text/csv",
      columnCount: columns.length,
      columns: columns.map((column, index) => ({ index: index + 1, required: true, ...column })),
    },
    schemaArtifact: {
      artifactId: options.schemaArtifactId || "",
      path: schemaArtifact.path || options.schemaPath || "",
      url: schemaArtifact.url || options.schemaUrl || "",
      filename: schemaArtifact.filename || options.schemaFilename || "",
      command: options.schemaCommand || "",
      curlCommand: schemaArtifact.curlCommand || options.schemaCurlCommand || "",
      contentType: "application/schema+json",
    },
    ...(options.extra || {}),
  };
}

