function buildPlanPackBundleCommandPresetWorkflowSnippetText(manifest, variant = "rich") {
  const artifactsJson = buildPlanPackBundleArtifactsJson(manifest);
  const workflowFamily = (artifactsJson.artifactFamilies || []).find((family) => family.id === "command-preset-workflow") || {};
  const commandPresetStepsCsvArtifact = (artifactsJson.artifacts || []).find((artifact) => artifact.id === "command-preset-steps-csv") || {};
  const hints = {
    familyId: workflowFamily.id || "command-preset-workflow",
    familyLabel: workflowFamily.label || "Command Preset Workflow",
    primaryArtifactId: workflowFamily.primaryArtifactId || "command-preset-steps-csv",
    recommendedOpenOrder: Array.isArray(workflowFamily.recommendedOpenOrder) ? workflowFamily.recommendedOpenOrder : ["command-preset-steps-csv"],
    target: commandPresetStepsCsvArtifact.url || commandPresetStepsCsvArtifact.path || manifest.commandPresetStepsCsvUrl || manifest.commandPresetStepsCsvPath || "",
    command: workflowFamily.downloadCommand || manifest.automation?.commandExamples?.commandPresetStepsCsv || "",
  };
  const policy = getPlanPackBundleCommandPresetSafetyPolicyFromAutomation(manifest.automation || {});
  const yesNo = (value) => value === true ? "yes" : value === false ? "no" : "";
  const formatSafetyStepRefs = (steps = []) => Array.isArray(steps) && steps.length
    ? steps.map((step) => {
      const ref = [step.presetId, step.key].filter(Boolean).join("/") || step.stepId || step.mode || step.role || "step";
      const label = step.label ? `label=${step.label}` : "";
      const rationale = step.rationale ? `reason=${step.rationale}` : "";
      return [ref, label, rationale].filter(Boolean).join(" ");
    }).join("; ")
    : "";
  const allowStepCount = Number.isFinite(policy.allowStepCount) ? policy.allowStepCount : null;
  const confirmStepCount = Number.isFinite(policy.confirmStepCount) ? policy.confirmStepCount : null;
  const denyStepCount = Number.isFinite(policy.denyStepCount) ? policy.denyStepCount : null;
  const hasDecisionCounts = allowStepCount !== null || confirmStepCount !== null || denyStepCount !== null;
  const lines = {
    family: hints.familyLabel || hints.familyId ? `Family: ${hints.familyLabel || hints.familyId}` : "",
    primaryArtifact: hints.primaryArtifactId ? `Primary artifact: ${hints.primaryArtifactId}` : "",
    openOrder: Array.isArray(hints.recommendedOpenOrder) && hints.recommendedOpenOrder.length ? `Open order: ${hints.recommendedOpenOrder.join(" -> ")}` : "",
    safetyDefaultDecision: policy.defaultDecision || policy.defaultExecutionDecision ? `Safety default decision: ${policy.defaultDecision || policy.defaultExecutionDecision}` : "",
    confirmationRequired: policy.confirmationRequired === true || policy.confirmationRequired === false ? `Confirmation required: ${yesNo(policy.confirmationRequired)}` : "",
    safeToAutoRun: policy.safeToAutoRun === true || policy.safeToAutoRun === false ? `Safe to auto-run: ${yesNo(policy.safeToAutoRun)}` : "",
    permissionScopes: Array.isArray(policy.permissionScopes) && policy.permissionScopes.length ? `Permission scopes: ${policy.permissionScopes.join(", ")}` : "",
    decisionCounts: hasDecisionCounts ? `Allow/confirm/deny steps: ${allowStepCount ?? 0}/${confirmStepCount ?? 0}/${denyStepCount ?? 0}` : "",
    confirmStepRefs: formatSafetyStepRefs(policy.confirmSteps) ? `Confirm step refs: ${formatSafetyStepRefs(policy.confirmSteps)}` : "",
    denyStepRefs: formatSafetyStepRefs(policy.denySteps) ? `Deny step refs: ${formatSafetyStepRefs(policy.denySteps)}` : "",
    url: hints.target ? `URL: ${hints.target}` : "",
    command: hints.command ? `Command: ${hints.command}` : "",
  };
  const variants = {
    compact: [
      "Command Preset Steps CSV",
      lines.family,
      lines.primaryArtifact,
      lines.openOrder,
      lines.safetyDefaultDecision,
      lines.confirmationRequired,
      lines.decisionCounts,
      lines.url,
      lines.command,
    ],
    artifact: [
      "Command Preset Steps CSV Artifact",
      lines.family,
      lines.primaryArtifact,
      lines.openOrder,
      lines.url,
    ],
    execution: [
      "Command Preset Steps CSV Execution",
      lines.safetyDefaultDecision,
      lines.confirmationRequired,
      lines.safeToAutoRun,
      lines.permissionScopes,
      lines.decisionCounts,
      lines.confirmStepRefs,
      lines.denyStepRefs,
      lines.command,
    ],
    rich: [
      "Command Preset Steps CSV",
      lines.family,
      lines.primaryArtifact,
      lines.openOrder,
      lines.safetyDefaultDecision,
      lines.confirmationRequired,
      lines.safeToAutoRun,
      lines.permissionScopes,
      lines.decisionCounts,
      lines.confirmStepRefs,
      lines.denyStepRefs,
      lines.url,
      lines.command,
    ],
  };
  return (variants[variant] || variants.rich).filter(Boolean).join("\n") + "\n";
}

