function buildPlanPackBundleArtifactFamilyIndex(artifactFamilies = []) {
  const familyIndex = new Map();
  (artifactFamilies || []).forEach((family) => {
    const recommendedOpenOrder = Array.isArray(family.recommendedOpenOrder) ? family.recommendedOpenOrder : [];
    (family.artifactIds || []).forEach((artifactId, index) => {
      familyIndex.set(artifactId, {
        familyId: family.id || "",
        familyLabel: family.label || "",
        familyOrder: index + 1,
        familyPrimary: artifactId === family.primaryArtifactId,
        familyPrimaryArtifactId: family.primaryArtifactId || "",
        familyRecommendedOpenOrder: recommendedOpenOrder,
        familyDownloadCommand: family.downloadCommand || "",
      });
    });
  });
  return familyIndex;
}

