    "  printf '%s\\n' \"PLAN_ID=$PLAN_ID\" \"SCOPE=$SCOPE\" \"IDS=$IDS\" \"ARTIFACTS_URL=$ARTIFACTS_URL\" \"ARTIFACTS_CSV_URL=$ARTIFACTS_CSV_URL\" \"ARTIFACTS_SCHEMA_URL=$ARTIFACTS_SCHEMA_URL\" \"ARTIFACT_FAMILIES_MARKDOWN_URL=$ARTIFACT_FAMILIES_MARKDOWN_URL\" \"ARTIFACT_FAMILIES_JSON_URL=$ARTIFACT_FAMILIES_JSON_URL\" \"ARTIFACT_FAMILIES_JSON_SCHEMA_URL=$ARTIFACT_FAMILIES_JSON_SCHEMA_URL\" \"SCHEMAS_INDEX_MARKDOWN_URL=$SCHEMAS_INDEX_MARKDOWN_URL\" \"SCHEMAS_INDEX_URL=$SCHEMAS_INDEX_URL\" \"SCHEMAS_INDEX_CSV_URL=$SCHEMAS_INDEX_CSV_URL\" \"SCHEMAS_INDEX_SCHEMA_URL=$SCHEMAS_INDEX_SCHEMA_URL\" \"SCHEMA_INDEX_CONTRACT_COVERAGE_STATUS=$SCHEMA_INDEX_CONTRACT_COVERAGE_STATUS\" \"SCHEMA_INDEX_CONTRACT_COVERAGE_OK=$SCHEMA_INDEX_CONTRACT_COVERAGE_OK\" \"SCHEMA_INDEX_CONTRACT_COVERAGE_ISSUE_COUNT=$SCHEMA_INDEX_CONTRACT_COVERAGE_ISSUE_COUNT\" \"SCHEMA_INDEX_CONTRACT_COVERAGE_RECOMMENDED_ACTION=$SCHEMA_INDEX_CONTRACT_COVERAGE_RECOMMENDED_ACTION\" \"WORKFLOW_PREFLIGHT_READINESS_STATUS=$WORKFLOW_PREFLIGHT_READINESS_STATUS\" \"WORKFLOW_PREFLIGHT_READINESS_OK=$WORKFLOW_PREFLIGHT_READINESS_OK\" \"WORKFLOW_PREFLIGHT_SCHEMA_COUNT=$WORKFLOW_PREFLIGHT_SCHEMA_COUNT\" \"WORKFLOW_PREFLIGHT_COMMAND_COUNT=$WORKFLOW_PREFLIGHT_COMMAND_COUNT\" \"WORKFLOW_PREFLIGHT_SOURCE_COUNT=$WORKFLOW_PREFLIGHT_SOURCE_COUNT\" \"WORKFLOW_PREFLIGHT_MISSING_COMMAND_SCHEMA_IDS=$WORKFLOW_PREFLIGHT_MISSING_COMMAND_SCHEMA_IDS\" \"WORKFLOW_PREFLIGHT_MISSING_SOURCE_SCHEMA_IDS=$WORKFLOW_PREFLIGHT_MISSING_SOURCE_SCHEMA_IDS\" \"WORKFLOW_PREFLIGHT_RECOMMENDED_ACTION=$WORKFLOW_PREFLIGHT_RECOMMENDED_ACTION\" \"COMMAND_PRESET_STEPS_CSV_URL=$COMMAND_PRESET_STEPS_CSV_URL\" \"COMMAND_PRESET_STEPS_SCHEMA_URL=$COMMAND_PRESET_STEPS_SCHEMA_URL\" \"COMMAND_PRESET_WORKFLOW_SNIPPET_URL=$COMMAND_PRESET_WORKFLOW_SNIPPET_URL\" \"COMMAND_PRESET_WORKFLOW_COMPACT_SNIPPET_URL=$COMMAND_PRESET_WORKFLOW_COMPACT_SNIPPET_URL\" \"COMMAND_PRESET_WORKFLOW_ARTIFACT_SNIPPET_URL=$COMMAND_PRESET_WORKFLOW_ARTIFACT_SNIPPET_URL\" \"COMMAND_PRESET_WORKFLOW_EXECUTION_SNIPPET_URL=$COMMAND_PRESET_WORKFLOW_EXECUTION_SNIPPET_URL\" \"COMMAND_PRESET_WORKFLOW_SNIPPETS_CSV_URL=$COMMAND_PRESET_WORKFLOW_SNIPPETS_CSV_URL\" \"COMMAND_PRESET_WORKFLOW_SNIPPETS_SCHEMA_URL=$COMMAND_PRESET_WORKFLOW_SNIPPETS_SCHEMA_URL\" \"MARKDOWN_URL=$MARKDOWN_URL\" \"MANIFEST_URL=$MANIFEST_URL\" \"LOCK_URL=$LOCK_URL\" \"LOCK_MARKDOWN_URL=$LOCK_MARKDOWN_URL\" \"SUMMARY_JSON_URL=$SUMMARY_JSON_URL\" \"HEALTH_JSON_URL=$HEALTH_JSON_URL\" \"HEALTH_MARKDOWN_URL=$HEALTH_MARKDOWN_URL\" \"HEALTH_CSV_URL=$HEALTH_CSV_URL\" \"HEALTH_BADGE_URL=$HEALTH_BADGE_URL\" \"HEALTH_METRICS_URL=$HEALTH_METRICS_URL\" \"HEALTH_ALERTS_URL=$HEALTH_ALERTS_URL\" \"HEALTH_DASHBOARD_URL=$HEALTH_DASHBOARD_URL\" \"HEALTH_EVENTS_URL=$HEALTH_EVENTS_URL\" \"HEALTH_EVENTS_SCHEMA_URL=$HEALTH_EVENTS_SCHEMA_URL\" \"HEALTH_EVENTS_VALIDATION_URL=$HEALTH_EVENTS_VALIDATION_URL\" \"HEALTH_EVENTS_ADAPTERS_URL=$HEALTH_EVENTS_ADAPTERS_URL\" \"HEALTH_EVENTS_ADAPTERS_MARKDOWN_URL=$HEALTH_EVENTS_ADAPTERS_MARKDOWN_URL\" \"HEALTH_EVENTS_ADAPTERS_SCHEMA_URL=$HEALTH_EVENTS_ADAPTERS_SCHEMA_URL\" \"HEALTH_EVENTS_ADAPTERS_CSV_URL=$HEALTH_EVENTS_ADAPTERS_CSV_URL\" \"HEALTH_EVENTS_VALIDATION_STATUS=$HEALTH_EVENTS_VALIDATION_STATUS\" \"HEALTH_EVENTS_VALIDATION_OK=$HEALTH_EVENTS_VALIDATION_OK\" \"HEALTH_EVENTS_MISSING_FIELD_COUNT=$HEALTH_EVENTS_MISSING_FIELD_COUNT\" \"HEALTH_EVENTS_ADAPTER_COUNT=$HEALTH_EVENTS_ADAPTER_COUNT\" \"HEALTH_EVENTS_ADAPTER_READY_COUNT=$HEALTH_EVENTS_ADAPTER_READY_COUNT\" \"HEALTH_EVENTS_ADAPTER_NEEDS_ATTENTION_COUNT=$HEALTH_EVENTS_ADAPTER_NEEDS_ATTENTION_COUNT\" \"HEALTH_EVENTS_ADAPTER_STATUSES=$HEALTH_EVENTS_ADAPTER_STATUSES\" \"HEALTH_REPORT_URL=$HEALTH_REPORT_URL\" \"HANDOFF_URL=$HANDOFF_URL\" \"ENV_URL=$ENV_URL\" \"COMMANDS_URL=$COMMANDS_URL\" \"INDEX_URL=$INDEX_URL\" \"RUNBOOK_URL=$RUNBOOK_URL\" \"VERIFICATION_URL=$VERIFICATION_URL\" \"VERIFICATION_JSON_URL=$VERIFICATION_JSON_URL\" \"VERIFICATION_CSV_URL=$VERIFICATION_CSV_URL\" \"CHECKSUMS_URL=$CHECKSUMS_URL\" \"CHECKSUMS_JSON_URL=$CHECKSUMS_JSON_URL\" \"CHECKSUMS_CSV_URL=$CHECKSUMS_CSV_URL\"",
    "}",
    "",
    "print_artifacts() {",
