    "    '  schemas-index-md Download only the bundle schema index Markdown file' \\",
    "    '  schemas-index Download only the bundle schema index JSON file' \\",
    "    '  schemas-index-csv Download only the bundle schema index CSV file' \\",
    "    '  schemas-index-schema Download only the bundle schema index CSV schema file' \\",
    "    '  command-preset-steps-csv Download only the command preset steps CSV file' \\",
    "    '  command-preset-steps-schema Download only the command preset steps CSV schema' \\",
    "    '  command-preset-workflow Download only the rich command preset workflow handoff snippet' \\",
    "    '  command-preset-workflow-compact Download only the compact command preset workflow handoff snippet' \\",
    "    '  command-preset-workflow-artifact Download only the artifact command preset workflow handoff snippet' \\",
    "    '  command-preset-workflow-execution Download only the execution command preset workflow handoff snippet' \\",
    "    '  command-preset-workflow-snippets-csv Download only the command preset workflow snippets CSV index' \\",
    "    '  command-preset-workflow-snippets-schema Download only the command preset workflow snippets CSV schema' \\",
