function buildPlanPackBundleWorkflowPreflightJson(manifest) {
  const schemaIndex = buildPlanPackBundleSchemasIndexJson(manifest);
  const schemaIndexContractCoverage = schemaIndex.contractCoverageSummary || {};
  const workflowPreflightJsonArtifact = (manifest.artifacts || []).find((artifact) => artifact.id === "workflow-preflight-json") || {};
  const workflowPreflightSchemaArtifact = (manifest.artifacts || []).find((artifact) => artifact.id === "workflow-preflight-schema") || {};
  const schemaCount = Number(schemaIndexContractCoverage.workflowPreflightSchemaCount || 0);
  const commandCount = Number(schemaIndexContractCoverage.workflowPreflightCommandCount || 0);
  const sourceCount = Number(schemaIndexContractCoverage.workflowPreflightSourceCount || 0);
  const missingCommandSchemaIds = Array.isArray(schemaIndexContractCoverage.missingWorkflowPreflightCommandSchemaIds) ? schemaIndexContractCoverage.missingWorkflowPreflightCommandSchemaIds : [];
  const missingSourceSchemaIds = Array.isArray(schemaIndexContractCoverage.missingWorkflowPreflightSourceSchemaIds) ? schemaIndexContractCoverage.missingWorkflowPreflightSourceSchemaIds : [];
  const ok = schemaCount > 0
    && commandCount >= schemaCount
    && sourceCount >= schemaCount
    && missingCommandSchemaIds.length === 0
    && missingSourceSchemaIds.length === 0;
  const schemaIndexReviewPath = manifest.schemasIndexMarkdownPath || manifest.schemasIndexPath || "";
  const schemaIndexReviewUrl = manifest.schemasIndexMarkdownUrl || manifest.schemasIndexUrl || "";
  const schemaIndexReviewKind = String(schemaIndexReviewPath || schemaIndexReviewUrl).includes(".md") ? "markdown" : "json";
  return {
    planId: manifest.planId,
    latestVersion: manifest.latestVersion || 1,
    generatedAt: manifest.generatedAt,
    filters: manifest.filters || {},
    filterSummary: manifest.filterSummary || "없음",
    scope: manifest.scope,
    scopeLabel: manifest.scopeLabel,
    packCount: manifest.packCount || 0,
    packIds: manifest.packIds || [],
    readiness: {
      target: 1,
      current: ok ? 1 : 0,
      ok,
      status: ok ? "met" : "breached",
      schemaCount,
      commandCount,
      sourceCount,
      missingCommandSchemaIds,
      missingSourceSchemaIds,
      recommendedAction: ok ? "Workflow preflight metadata is ready." : "Review Workflow preflight command/source metadata in Schema Index before wiring automated handoff consumers.",
    },
    schemaIndexReview: {
      kind: schemaIndexReviewKind,
      path: schemaIndexReviewPath,
      url: schemaIndexReviewUrl,
    },
    command: {
      mode: manifest.automation?.commandModeIndex?.workflowPreflight?.mode || "workflow-preflight",
      text: manifest.automation?.commandExamples?.workflowPreflight || "",
      sourcePath: manifest.commandsPath || "",
      sourceUrl: manifest.commandsUrl || "",
    },
    downloads: {
      payload: {
        mode: manifest.automation?.commandModeIndex?.workflowPreflightJson?.mode || "workflow-preflight-json",
        command: manifest.automation?.commandExamples?.workflowPreflightJson || "",
        path: workflowPreflightJsonArtifact.path || "",
        url: workflowPreflightJsonArtifact.url || "",
        filename: workflowPreflightJsonArtifact.filename || "",
      },
      schema: {
        mode: manifest.automation?.commandModeIndex?.workflowPreflightSchema?.mode || "workflow-preflight-schema",
        command: manifest.automation?.commandExamples?.workflowPreflightSchema || "",
        path: workflowPreflightSchemaArtifact.path || "",
        url: workflowPreflightSchemaArtifact.url || "",
        filename: workflowPreflightSchemaArtifact.filename || "",
      },
    },
    schemaIndexContractCoverage,
  };
}

function buildPlanPackBundleWorkflowPreflightSchemaJson() {
  return {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://travel-planner.local/schemas/bundle-workflow-preflight.schema.json",
    title: "Workflow preflight handoff",
    description: "Contract for packs.bundle.workflow-preflight.json.",
    type: "object",
    additionalProperties: false,
    required: ["planId", "latestVersion", "generatedAt", "readiness", "schemaIndexReview", "command", "downloads", "schemaIndexContractCoverage"],
    properties: {
      planId: { type: "string" },
      latestVersion: { type: "integer", minimum: 1 },
      generatedAt: { type: "string" },
      filters: { type: "object", additionalProperties: true },
      filterSummary: { type: "string" },
      scope: { type: "string", enum: ["visible", "selected", "all", ""] },
      scopeLabel: { type: "string" },
      packCount: { type: "integer", minimum: 0 },
      packIds: { type: "array", items: { type: "string" } },
      readiness: {
        type: "object",
        additionalProperties: false,
        required: ["target", "current", "ok", "status", "schemaCount", "commandCount", "sourceCount", "missingCommandSchemaIds", "missingSourceSchemaIds", "recommendedAction"],
        properties: {
          target: { type: "integer", enum: [1] },
          current: { type: "integer", enum: [0, 1] },
          ok: { type: "boolean" },
          status: { type: "string", enum: ["met", "breached"] },
          schemaCount: { type: "integer", minimum: 0 },
          commandCount: { type: "integer", minimum: 0 },
          sourceCount: { type: "integer", minimum: 0 },
          missingCommandSchemaIds: { type: "array", items: { type: "string" } },
          missingSourceSchemaIds: { type: "array", items: { type: "string" } },
          recommendedAction: { type: "string" },
        },
      },
      schemaIndexReview: {
        type: "object",
        additionalProperties: false,
        required: ["kind", "path", "url"],
        properties: {
          kind: { type: "string", enum: ["markdown", "json"] },
          path: { type: "string" },
          url: { type: "string" },
        },
      },
      command: {
        type: "object",
        additionalProperties: false,
        required: ["mode", "text", "sourcePath", "sourceUrl"],
        properties: {
          mode: { type: "string", enum: ["workflow-preflight"] },
          text: { type: "string" },
          sourcePath: { type: "string" },
          sourceUrl: { type: "string" },
        },
      },
      downloads: {
        type: "object",
        additionalProperties: false,
        required: ["payload", "schema"],
        properties: {
          payload: {
            type: "object",
            additionalProperties: false,
            required: ["mode", "command", "path", "url", "filename"],
            properties: {
              mode: { type: "string", enum: ["workflow-preflight-json"] },
              command: { type: "string" },
              path: { type: "string" },
              url: { type: "string" },
              filename: { type: "string" },
            },
          },
          schema: {
            type: "object",
            additionalProperties: false,
            required: ["mode", "command", "path", "url", "filename"],
            properties: {
              mode: { type: "string", enum: ["workflow-preflight-schema"] },
              command: { type: "string" },
              path: { type: "string" },
              url: { type: "string" },
              filename: { type: "string" },
            },
          },
        },
      },
      schemaIndexContractCoverage: { type: "object", additionalProperties: true },
    },
  };
}

