function buildPlanPackBundleHealthEventsAdaptersJson(manifest) {
  const payload = buildPlanPackBundleHealthEventsJson(manifest);
  const validation = buildPlanPackBundleHealthEventsValidationJson(manifest);
  const readiness = validation.adapterReadiness || {};
  const usageHints = payload.consumerUsageHints || {};
  const contractHints = usageHints.consumerAdapterContractHints || {};
  const adapters = Array.isArray(readiness.adapters) ? readiness.adapters : [];
  const countValue = (value, fallback) => Number.isFinite(Number(value)) ? Number(value) : fallback;
  const missingFieldCount = countValue(validation.missingFieldCount, 0);
  const validationStatus = validation.status || validation.validationStatus || (missingFieldCount ? "needs-attention" : "pass");
  const validationOk = validation.ok === undefined && validation.validationOk === undefined ? validationStatus === "pass" || validationStatus === "ok" : Boolean(validation.ok ?? validation.validationOk);
  const schemaIndexContractCoverage = validation.schemaIndexContractCoverage || payload.schemaIndexContractCoverage || {};
  const schemaIndexCoverageIssueCount = countValue(schemaIndexContractCoverage.issueCount, 0);
  const schemaIndexCoverageStatus = schemaIndexContractCoverage.status || (schemaIndexCoverageIssueCount ? "needs_attention" : "ready");
  const schemaIndexCoverageOk = schemaIndexContractCoverage.ok === undefined ? schemaIndexCoverageStatus === "ready" : schemaIndexContractCoverage.ok === true;
  const schemaIndexCoverageRecommendedAction = schemaIndexContractCoverage.recommendedAction || (schemaIndexCoverageOk ? "Schema Index contracts are ready." : "Review Schema Index contract coverage before wiring adapter consumers.");
  const familyDownloadCommands = validation.familyDownloadCommands || payload.familyDownloadCommands || {};
  const familyRecoveryActions = Array.isArray(validation.familyRecoveryActions)
    ? validation.familyRecoveryActions
    : Array.isArray(payload.familyRecoveryActions)
      ? payload.familyRecoveryActions
      : [];
  const workflowArtifactHints = validation.workflowArtifactHints || payload.workflowArtifactHints || {};
  const familyRecoveryOrder = familyRecoveryActions.map((action) => action.familyId || action.id || "").filter(Boolean);
  return {
    schemaVersion: "1.0",
    adapterReadinessContractId: "travel-planner.bundle-health-events-adapter-readiness.v1",
    planId: validation.planId ?? payload.planId ?? manifest.planId,
    latestVersion: validation.latestVersion ?? payload.latestVersion ?? manifest.latestVersion ?? 1,
    generatedAt: validation.generatedAt || payload.generatedAt || manifest.generatedAt || new Date().toISOString(),
    scope: validation.scope || payload.scope || manifest.scope || "visible",
    scopeLabel: validation.scopeLabel || payload.scopeLabel || manifest.scopeLabel || "",
    validationStatus,
    validationOk,
    missingFieldCount,
    schemaIndexContractCoverage,
    source: {
      eventsPath: manifest.healthEventsPath || manifest.paths?.healthEvents || "",
      eventsUrl: manifest.healthEventsUrl || manifest.urls?.healthEvents || "",
      schemaPath: manifest.healthEventsSchemaPath || manifest.paths?.healthEventsSchema || "",
      schemaUrl: manifest.healthEventsSchemaUrl || manifest.urls?.healthEventsSchema || "",
      validationPath: manifest.healthEventsValidationPath || manifest.paths?.healthEventsValidation || "",
      validationUrl: manifest.healthEventsValidationUrl || manifest.urls?.healthEventsValidation || "",
      adaptersPath: manifest.healthEventsAdaptersPath || manifest.paths?.healthEventsAdapters || "",
      adaptersUrl: manifest.healthEventsAdaptersUrl || manifest.urls?.healthEventsAdapters || "",
      adaptersMarkdownPath: manifest.healthEventsAdaptersMarkdownPath || manifest.paths?.healthEventsAdaptersMarkdown || "",
      adaptersMarkdownUrl: manifest.healthEventsAdaptersMarkdownUrl || manifest.urls?.healthEventsAdaptersMarkdown || "",
      adaptersSchemaPath: manifest.healthEventsAdaptersSchemaPath || manifest.paths?.healthEventsAdaptersSchema || "",
      adaptersSchemaUrl: manifest.healthEventsAdaptersSchemaUrl || manifest.urls?.healthEventsAdaptersSchema || "",
      adaptersCsvPath: manifest.healthEventsAdaptersCsvPath || manifest.paths?.healthEventsAdaptersCsv || "",
      adaptersCsvUrl: manifest.healthEventsAdaptersCsvUrl || manifest.urls?.healthEventsAdaptersCsv || "",
      commandPresetStepsCsvTarget: workflowArtifactHints.target || "",
    },
    summary: {
      adapterCount: countValue(readiness.adapterCount, adapters.length),
      readyCount: countValue(readiness.readyCount, adapters.filter((adapter) => adapter.readinessStatus === "ready" || adapter.status === "ready").length),
      needsAttentionCount: countValue(readiness.needsAttentionCount, adapters.filter((adapter) => adapter.readinessStatus === "needs-attention" || adapter.status === "needs-attention").length),
      defaultSinkIds: Array.isArray(readiness.defaultSinkIds) ? readiness.defaultSinkIds : payload.recommendedSinks || [],
      familyRecoveryActionCount: familyRecoveryActions.length,
      familyRecoveryOrder,
      workflowArtifactTarget: workflowArtifactHints.target || "",
      workflowArtifactCommand: workflowArtifactHints.command || "",
      schemaIndexCoverageStatus,
      schemaIndexCoverageOk,
      schemaIndexCoverageIssueCount,
      schemaIndexCoverageRecommendedAction,
    },
    adapters,
    familyDownloadCommands,
    familyRecoveryActions,
    workflowArtifactHints,
    dispatchGuidance: validation.dispatchGuidance || readiness.dispatchGuidance || [],
    implementationChecklist: contractHints.implementationChecklist || [],
    compatibilityRules: contractHints.compatibilityRules || [],
  };
}

function buildPlanPackBundleHealthEventsAdaptersMarkdown(manifest) {
  const readiness = buildPlanPackBundleHealthEventsAdaptersJson(manifest);
  const summary = readiness.summary || {};
  const source = readiness.source || {};
  const adapters = Array.isArray(readiness.adapters) ? readiness.adapters : [];
  const checklist = Array.isArray(readiness.implementationChecklist) ? readiness.implementationChecklist : [];
  const compatibilityRules = Array.isArray(readiness.compatibilityRules) ? readiness.compatibilityRules : [];
  const familyRecoveryActions = Array.isArray(readiness.familyRecoveryActions) ? readiness.familyRecoveryActions : [];
  const workflowArtifactHints = readiness.workflowArtifactHints || {};
  const schemaIndexCoverage = readiness.schemaIndexContractCoverage || {};
  const schemaIndexCoverageStatus = summary.schemaIndexCoverageStatus || schemaIndexCoverage.status || "n/a";
  const schemaIndexCoverageOk = summary.schemaIndexCoverageOk === undefined ? schemaIndexCoverage.ok === true : summary.schemaIndexCoverageOk === true;
  const schemaIndexCoverageIssueCount = summary.schemaIndexCoverageIssueCount ?? schemaIndexCoverage.issueCount ?? 0;
  const schemaIndexCoverageRecommendedAction = summary.schemaIndexCoverageRecommendedAction || schemaIndexCoverage.recommendedAction || "";
  const mdCell = (value) => String(value || "").replace(/\|/g, "\\|").replace(/\r?\n/g, " ");
  const joinList = (value) => Array.isArray(value) ? value.join(", ") : value || "";
  const listItemText = (item) => {
    if (!item || typeof item !== "object") return String(item || "");
    return item.label || item.title || item.description || item.action || JSON.stringify(item);
  };
  const rows = adapters.map((adapter) => [
    adapter.adapterId || "",
    adapter.payloadField || "",
    adapter.readinessStatus || "",
    adapter.selectedByDefault ? "yes" : "no",
    joinList(adapter.missingInputPaths),
    joinList(adapter.requiredReceiptPaths),
    adapter.recommendedAction || "",
  ]);
  const recoveryRows = familyRecoveryActions.map((action) => [
    action.familyId || action.id || "",
    action.target || action.familyLabel || "",
    action.primaryArtifactId || "",
    joinList(action.recommendedOpenOrder),
    action.command || "",
    action.reason || action.recommendedAction || "",
  ]);
  return [
    `# 플랜 #${readiness.planId || manifest.planId} Health Events Adapter Readiness`,
    "",
    `- 범위: ${readiness.scopeLabel || readiness.scope || manifest.scopeLabel || manifest.scope || "visible"}`,
    `- 필터: ${readiness.filterSummary || manifest.filterSummary || "없음"}`,
    `- validation status: ${readiness.validationStatus || "n/a"}`,
    `- validation ok: ${readiness.validationOk ? "yes" : "no"}`,
    `- adapter readiness: ${summary.readyCount || 0}/${summary.adapterCount || 0} ready, ${summary.needsAttentionCount || 0} needs attention`,
    `- Schema Index coverage: ${schemaIndexCoverageStatus}, ${schemaIndexCoverageIssueCount} issue(s)`,
    `- default sinks: ${joinList(summary.defaultSinkIds) || "없음"}`,
    `- family recovery actions: ${summary.familyRecoveryActionCount ?? familyRecoveryActions.length}`,
    `- workflow artifact target: ${workflowArtifactHints.target || summary.workflowArtifactTarget || "없음"}`,
    "",
    "## Source links",
    "",
    `- Health Events JSON: ${source.healthEventsUrl || source.healthEventsPath || ""}`,
    `- Health Events Validation JSON: ${source.validationUrl || source.validationPath || ""}`,
    `- Adapter Readiness JSON: ${source.adaptersUrl || source.adaptersPath || ""}`,
    `- Adapter Readiness Schema JSON: ${source.adaptersSchemaUrl || source.adaptersSchemaPath || ""}`,
    `- Adapter Readiness CSV: ${source.adaptersCsvUrl || source.adaptersCsvPath || ""}`,
    `- Command Preset Steps CSV: ${workflowArtifactHints.target || source.commandPresetStepsCsvTarget || ""}`,
    "",
    "## Schema Index contract coverage",
    "",
    `- status: ${schemaIndexCoverageStatus}`,
    `- ok: ${schemaIndexCoverageOk ? "yes" : "no"}`,
    `- issue count: ${schemaIndexCoverageIssueCount}`,
    `- recommended action: ${schemaIndexCoverageRecommendedAction || "없음"}`,
    "",
    "## Workflow artifact hints",
    "",
    workflowArtifactHints.target || workflowArtifactHints.command ? `- family: ${workflowArtifactHints.familyLabel || workflowArtifactHints.familyId || "Command Preset Workflow"}` : "- workflow artifact hint 없음",
    workflowArtifactHints.target ? `- target: ${workflowArtifactHints.target}` : "",
    workflowArtifactHints.command ? `- command: ${workflowArtifactHints.command}` : "",
    workflowArtifactHints.jsonPaths ? `- JSONPath: ${Object.entries(workflowArtifactHints.jsonPaths).map(([key, value]) => `${key}=${value}`).join(", ")}` : "",
    "",
    "## Artifact family recovery",
    "",
    recoveryRows.length ? "| family | target | primary artifact | open order | command | reason |" : "- family recovery action 없음",
    recoveryRows.length ? "|---|---|---|---|---|---|" : "",
    ...recoveryRows.map((row) => `| ${row.map(mdCell).join(" | ")} |`),
    "",
    "## Adapter matrix",
    "",
    rows.length ? "| adapter | payload | readiness | default sink | missing inputs | receipt paths | recommended action |" : "- adapter readiness 없음",
    rows.length ? "|---|---|---|---|---|---|---|" : "",
    ...rows.map((row) => `| ${row.map(mdCell).join(" | ")} |`),
    "",
    "## Implementation checklist",
    "",
    ...(checklist.length ? checklist.map((item) => `- ${listItemText(item)}`) : ["- 추가 checklist 없음"]),
    "",
    "## Compatibility rules",
    "",
    ...(compatibilityRules.length ? compatibilityRules.map((item) => `- ${listItemText(item)}`) : ["- 추가 compatibility rule 없음"]),
  ].join("\n") + "\n";
}

function buildPlanPackBundleHealthEventsAdaptersSchemaJson() {
  return {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://travel-planner.local/schemas/bundle-health-events-adapter-readiness.schema.json",
    title: "Travel Planner Bundle Health Events Adapter Readiness",
    type: "object",
    additionalProperties: true,
    required: ["schemaVersion", "adapterReadinessContractId", "planId", "generatedAt", "validationStatus", "validationOk", "summary", "adapters"],
    properties: {
      schemaVersion: { type: "string", const: "1.0" },
      adapterReadinessContractId: { type: "string", const: "travel-planner.bundle-health-events-adapter-readiness.v1" },
      planId: { type: ["string", "number"] },
      latestVersion: { type: "integer", minimum: 1 },
      generatedAt: { type: "string", format: "date-time" },
      scope: { type: "string" },
      scopeLabel: { type: "string" },
      validationStatus: { type: "string", enum: ["pass", "ok", "needs-attention", "warning", "failed"] },
      validationOk: { type: "boolean" },
      missingFieldCount: { type: "integer", minimum: 0 },
      schemaIndexContractCoverage: {
        type: "object",
        additionalProperties: true,
        properties: {
          ok: { type: "boolean" },
          status: { type: "string", enum: ["ready", "needs_attention"] },
          issueCount: { type: "integer", minimum: 0 },
          recommendedAction: { type: "string" },
        },
      },
      source: {
        type: "object",
        additionalProperties: true,
        properties: {
          eventsPath: { type: "string" },
          eventsUrl: { type: "string" },
          schemaPath: { type: "string" },
          schemaUrl: { type: "string" },
          validationPath: { type: "string" },
          validationUrl: { type: "string" },
          adaptersPath: { type: "string" },
          adaptersUrl: { type: "string" },
          adaptersCsvPath: { type: "string" },
          adaptersCsvUrl: { type: "string" },
        },
      },
      summary: {
        type: "object",
        additionalProperties: true,
        required: ["adapterCount", "readyCount", "needsAttentionCount", "defaultSinkIds"],
        properties: {
          adapterCount: { type: "integer", minimum: 0 },
          readyCount: { type: "integer", minimum: 0 },
          needsAttentionCount: { type: "integer", minimum: 0 },
          defaultSinkIds: { type: "array", items: { type: "string" } },
          familyRecoveryActionCount: { type: "integer", minimum: 0 },
          familyRecoveryOrder: { type: "array", items: { type: "string" } },
          schemaIndexCoverageStatus: { type: "string", enum: ["ready", "needs_attention"] },
          schemaIndexCoverageOk: { type: "boolean" },
          schemaIndexCoverageIssueCount: { type: "integer", minimum: 0 },
          schemaIndexCoverageRecommendedAction: { type: "string" },
        },
      },
      adapters: {
        type: "array",
        items: {
          type: "object",
          additionalProperties: true,
          required: ["adapterId", "payloadField", "readinessStatus"],
          properties: {
            order: { type: "integer", minimum: 1 },
            adapterId: { type: "string" },
            payloadField: { type: "string" },
            readinessStatus: { type: "string", enum: ["ready", "needs-attention", "unknown"] },
            selectedByDefault: { type: "boolean" },
            missingInputPathCount: { type: "integer", minimum: 0 },
            missingInputPaths: { type: "array", items: { type: "string" } },
            requiredReceiptPathCount: { type: "integer", minimum: 0 },
            requiredReceiptPaths: { type: "array", items: { type: "string" } },
            recommendedAction: { type: "string" },
            endpointEnv: { type: "string" },
            secretEnv: { type: "string" },
            idempotencyPath: { type: "string" },
          },
        },
      },
      familyDownloadCommands: { type: "object", additionalProperties: { type: "string" } },
      familyRecoveryActions: {
        type: "array",
        items: {
          type: "object",
          additionalProperties: true,
          properties: {
            familyId: { type: "string" },
            id: { type: "string" },
            target: { type: "string" },
            primaryArtifactId: { type: "string" },
            recommendedOpenOrder: { type: "array", items: { type: "string" } },
            command: { type: "string" },
            reason: { type: "string" },
          },
        },
      },
      workflowArtifactHints: {
        type: "object",
        additionalProperties: true,
        properties: {
          schemaVersion: { type: "string" },
          familyId: { type: "string" },
          familyLabel: { type: "string" },
          primaryArtifactId: { type: "string" },
          artifactIds: { type: "array", items: { type: "string" } },
          recommendedOpenOrder: { type: "array", items: { type: "string" } },
          target: { type: "string" },
          command: { type: "string" },
          jsonPaths: { type: "object", additionalProperties: { type: "string" } },
          useWhen: { type: "string" },
        },
      },
      dispatchGuidance: { type: ["object", "array"] },
      implementationChecklist: { type: "array", items: { type: "string" } },
      compatibilityRules: { type: "array", items: { type: "string" } },
    },
  };
}

function getPlanPackBundleHealthEventsAdaptersCsvColumns() {
  const integerColumns = new Set(["latest_version", "adapter_count", "ready_count", "needs_attention_count", "family_recovery_action_count", "family_recovery_order", "schema_index_contract_coverage_issue_count", "adapter_order", "missing_input_path_count", "required_receipt_path_count"]);
  return [
    "plan_id",
    "latest_version",
    "generated_at",
    "scope",
    "scope_label",
    "validation_status",
    "validation_ok",
    "schema_index_contract_coverage_status",
    "schema_index_contract_coverage_ok",
    "schema_index_contract_coverage_issue_count",
    "schema_index_contract_coverage_recommended_action",
    "family_recovery_action_count",
    "family_recovery_order",
    "adapter_order",
    "adapter_id",
    "payload_field",
    "readiness_status",
    "selected_by_default",
    "missing_input_path_count",
    "missing_input_paths",
    "required_receipt_path_count",
    "required_receipt_paths",
    "recommended_action",
    "endpoint_env",
    "secret_env",
    "idempotency_path",
    "validation_url",
    "schema_url",
    "workflow_family_id",
    "workflow_artifact_target",
    "workflow_artifact_command",
  ].map((name) => ({
    name,
    type: integerColumns.has(name) ? "integer" : "string",
    ...(["validation_ok", "schema_index_contract_coverage_ok", "selected_by_default"].includes(name) ? { enum: ["true", "false"] } : {}),
  }));
}

function buildPlanPackBundleHealthEventsAdaptersCsvSchemaJson(manifest) {
  return buildPlanPackBundleCsvSchemaJson(manifest, {
    title: "Adapter Readiness CSV Row",
    description: "Column contract for packs.bundle.health.events.adapters.csv.",
    csvArtifactId: "health-events-adapters-csv",
    schemaArtifactId: "health-events-adapters-csv-schema",
    columns: getPlanPackBundleHealthEventsAdaptersCsvColumns(),
    csvPath: manifest.healthEventsAdaptersCsvPath || "",
    csvUrl: manifest.healthEventsAdaptersCsvUrl || "",
    csvFilename: manifest.automation?.filenames?.healthEventsAdaptersCsv || manifest.filenames?.healthEventsAdaptersCsv || "",
    schemaPath: manifest.healthEventsAdaptersCsvSchemaPath || "",
    schemaUrl: manifest.healthEventsAdaptersCsvSchemaUrl || "",
    schemaFilename: manifest.automation?.filenames?.healthEventsAdaptersCsvSchema || manifest.filenames?.healthEventsAdaptersCsvSchema || "",
    schemaCommand: manifest.automation?.commandExamples?.healthEventsAdaptersCsvSchema || "",
    schemaCurlCommand: manifest.automation?.curlCommands?.healthEventsAdaptersCsvSchema || "",
  });
}

function buildPlanPackBundleHealthEventsAdaptersCsv(manifest) {
  const readiness = buildPlanPackBundleHealthEventsAdaptersJson(manifest);
  const toList = (value) => Array.isArray(value) ? value : value ? [value] : [];
  const columns = getPlanPackBundleHealthEventsAdaptersCsvColumns().map((column) => column.name);
  const workflowArtifactHints = readiness.workflowArtifactHints || {};
  const rows = (readiness.adapters || []).map((adapter, index) => {
    const missingInputPaths = toList(adapter.missingInputPaths);
    const requiredReceiptPaths = toList(adapter.requiredReceiptPaths);
    return [
      readiness.planId,
      readiness.latestVersion || 1,
      readiness.generatedAt,
      readiness.scope,
      readiness.scopeLabel,
      readiness.validationStatus,
      readiness.validationOk ? "true" : "false",
      readiness.summary?.schemaIndexCoverageStatus || "",
      readiness.summary?.schemaIndexCoverageOk ? "true" : "false",
      readiness.summary?.schemaIndexCoverageIssueCount ?? 0,
      readiness.summary?.schemaIndexCoverageRecommendedAction || "",
      readiness.summary?.familyRecoveryActionCount ?? 0,
      toList(readiness.summary?.familyRecoveryOrder).join("; "),
      adapter.order || index + 1,
      adapter.adapterId || adapter.id || "",
      adapter.payloadField || adapter.payloadPath || "",
      adapter.readinessStatus || adapter.status || "",
      adapter.selectedByDefault || adapter.defaultSink ? "true" : "false",
      adapter.missingInputPathCount ?? missingInputPaths.length,
      missingInputPaths.join("; "),
      adapter.requiredReceiptPathCount ?? requiredReceiptPaths.length,
      requiredReceiptPaths.join("; "),
      adapter.recommendedAction || adapter.nextAction || "",
      adapter.endpointEnv || adapter.endpointEnvKey || adapter.endpointUrlEnv || "",
      adapter.secretEnv || adapter.secretEnvKey || "",
      adapter.idempotencyPath || "",
      readiness.source?.validationUrl || readiness.source?.validationPath || "",
      readiness.source?.schemaUrl || readiness.source?.schemaPath || "",
      workflowArtifactHints.familyId || "",
      workflowArtifactHints.target || readiness.summary?.workflowArtifactTarget || "",
      workflowArtifactHints.command || readiness.summary?.workflowArtifactCommand || "",
    ].map(csvCell).join(",");
  });
  return [columns.join(","), ...rows].join("\n") + "\n";
}

app.get("/api/plans/:id/packs.bundle.health.events.schema.json", async (req, res) => {
  const plan = await getPlan(req.params.id, DB_PATH);
  if (!plan) return res.status(404).json({ error: "not found" });
  const catalog = selectPlanPackCatalogByIds(
    filterPlanPackCatalog(
      buildPlanPackCatalog(plan, { baseUrl: `${req.protocol}://${req.get("host")}` }),
      packCatalogFilterFromQuery(req.query)
    ),
    packCatalogIdsFromQuery(req.query)
  );
  const includeAll = ["1", "true", "yes", "on"].includes(String(req.query.all || "").trim().toLowerCase());
  const scope = String(req.query.scope || "").trim().toLowerCase();
  const filenameScope = scope === "selected" ? "selected" : includeAll ? "all" : "visible";
  res.setHeader("Content-Type", "application/schema+json; charset=utf-8");
  res.setHeader("Content-Disposition", `attachment; filename="travel-plan-${plan.id}-${filenameScope}-packs-health-events-schema${packCatalogFilenameSuffix(catalog, { includeAll })}.json"`);
  res.send(jsonText(buildPlanPackBundleHealthEventsSchemaJson()));
});

