app.post("/api/plans/:id/expense", async (req, res) => {
  const plan = await getPlan(req.params.id, DB_PATH);
  if (!plan) return res.status(404).json({ error: "not found" });
  try {
    const result = await addPlanExpense(plan.id, req.body || {}, DB_PATH);
    res.status(201).json({
      planId: result.plan.id,
      expense: result.expense,
      expenses: result.plan.expenses || [],
      briefing: buildExpenseLedger(result.plan),
    });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

