app.post("/api/plans/:id/pin", async (req, res) => {
  const plan = await getPlan(req.params.id, DB_PATH);
  if (!plan) return res.status(404).json({ error: "not found" });
  const pinned = typeof req.body.pinned === "boolean" ? req.body.pinned : !plan.pinned;
  const updatedPlan = await setPlanPinned(plan.id, pinned, DB_PATH);
  res.json(updatedPlan);
});

app.post("/api/plans/:id/duplicate", async (req, res) => {
  const plan = await getPlan(req.params.id, DB_PATH);
  if (!plan) return res.status(404).json({ error: "not found" });
  const duplicated = await duplicatePlan(plan.id, {}, DB_PATH);
  res.status(201).json(duplicated);
});

app.post("/api/plans/:id/schedule", async (req, res) => {
  const plan = await getPlan(req.params.id, DB_PATH);
  if (!plan) return res.status(404).json({ error: "not found" });

  const startDate = String(req.body.startDate || plan.startDate || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate)) {
    return res.status(400).json({ error: "startDate must be YYYY-MM-DD" });
  }
  const nights = Math.max(1, Number(req.body.nights ?? plan.nights) || Number(plan.nights) || 1);
  const updatedPlan = await updatePlanSchedule(plan.id, { startDate, nights }, DB_PATH);
  res.json(updatedPlan);
});

app.post("/api/plans/:id/party-budget", async (req, res) => {
  const plan = await getPlan(req.params.id, DB_PATH);
  if (!plan) return res.status(404).json({ error: "not found" });

  const travelers = Math.max(1, Number(req.body.travelers ?? plan.travelers) || Number(plan.travelers) || 1);
  const budgetPerPerson = req.body.budgetPerPerson === "" ? null : req.body.budgetPerPerson ?? plan.budgetPerPerson ?? null;
  const updatedPlan = await updatePlanPartyBudget(plan.id, { travelers, budgetPerPerson }, DB_PATH);
  res.json(updatedPlan);
});

app.post("/api/plans/:id/note", async (req, res) => {
  const plan = await getPlan(req.params.id, DB_PATH);
  if (!plan) return res.status(404).json({ error: "not found" });

  const updatedPlan = await updatePlanPersonalNote(plan.id, req.body.personalNote || "", DB_PATH);
  res.json(updatedPlan);
});

app.post("/api/plans", async (req, res) => {
  const input = req.body || {};
  const normalizedInput = {
    destination: input.destination,
    departure: input.departure,
    country: input.country,
    scope: input.scope,
    companions: input.companions,
    travelers: input.travelers,
    nights: input.nights,
    tripType: input.tripType,
    accommodation: input.accommodation,
    transportPref: input.transportPref,
    startDate: input.startDate,
    endDate: input.endDate,
    budgetPerPerson: input.budgetPerPerson,
    notes: input.notes,
    highlights: input.highlights,
  };

  const llmOptions = extractLlmOptions(input);
  clearRequestLlmApiKey(input);
  preventSensitiveLlmCaching(res, llmOptions);
  const llmError = llmOptionsError(llmOptions);
  if (llmError) {
    return res.status(400).json({ error: llmError });
  }
  if (REQUIRE_USER_LLM_KEY && (!llmOptions?.provider || !llmOptions?.apiKey)) {
    return res.status(400).json({ error: "user llm api key required" });
  }

  const generation = attachLlmAudit(await generatePlan(normalizedInput, null, null, llmOptions), llmOptions);
  if (llmOptions?.apiKey && generation.error) {
    return res.status(502).json({ error: "llm provider failed" });
  }
  const plan = await createPlan(normalizedInput, generation, DB_PATH);
  if (generation.error) {
    plan.latestError = generation.error;
  }
  res.status(201).json(plan);
});

app.post("/api/plans/:id/refine", async (req, res) => {
  const plan = await getPlan(req.params.id, DB_PATH);
  if (!plan) return res.status(404).json({ error: "not found" });

  const feedback = req.body.feedback;
  if (!feedback || !String(feedback).trim()) {
    return res.status(400).json({ error: "feedback required" });
  }

  const latest = plan.revisions.find((r) => r.version === plan.latestVersion);
  const input = req.body || {};
  const llmOptions = extractLlmOptions(input);
  clearRequestLlmApiKey(input);
  preventSensitiveLlmCaching(res, llmOptions);
  const llmError = llmOptionsError(llmOptions);
  if (llmError) {
    return res.status(400).json({ error: llmError });
  }
  if (REQUIRE_USER_LLM_KEY && (!llmOptions?.provider || !llmOptions?.apiKey)) {
    return res.status(400).json({ error: "user llm api key required" });
  }

  const generation = attachLlmAudit(await generatePlan(plan, latest?.planText, feedback, llmOptions), llmOptions);
  if (llmOptions?.apiKey && generation.error) {
    return res.status(502).json({ error: "llm provider failed" });
  }
  const updatedPlan = await refinePlan(plan.id, generation, feedback, DB_PATH);
  if (generation.error) {
    updatedPlan.latestError = generation.error;
  }
  res.json(updatedPlan);
}
);

app.get("/plans/:id", async (req, res) => {
  res.sendFile(path.join(__dirname, "public", "plan.html"));
});

function isLocalhostName(hostname) {
  return ["localhost", "127.0.0.1", "::1"].includes(hostname);
}

function localNetworkOrigins(port = PORT) {
  return Object.values(os.networkInterfaces())
    .flatMap((entries) => entries || [])
    .filter((entry) => entry && entry.family === "IPv4" && !entry.internal)
    .map((entry) => `http://${entry.address}:${port}`);
}

function normalizePublicOrigin(origin) {
  if (!origin) return "";
  try {
    const url = new URL(origin);
    if (!["http:", "https:"].includes(url.protocol)) return "";
    url.pathname = "";
    url.search = "";
    url.hash = "";
    return url.toString().replace(/\/$/, "");
  } catch {
    return "";
  }
}

const QR_ECC_M_TABLE = [
  null,
  { dataCodewords: 16, ecCodewords: 10, blocks: [16] },
  { dataCodewords: 28, ecCodewords: 16, blocks: [28] },
  { dataCodewords: 44, ecCodewords: 26, blocks: [44] },
  { dataCodewords: 64, ecCodewords: 18, blocks: [32, 32] },
  { dataCodewords: 86, ecCodewords: 24, blocks: [43, 43] },
  { dataCodewords: 108, ecCodewords: 16, blocks: [27, 27, 27, 27] },
];

const QR_ALIGNMENT_CENTERS = [
  null,
  [],
  [6, 18],
  [6, 22],
  [6, 26],
  [6, 30],
  [6, 34],
];

const QR_FORMAT_M_MASK_0 = 0b101010000010010;

function qrByteCapacity(version) {
  const dataBits = QR_ECC_M_TABLE[version].dataCodewords * 8;
  return Math.floor((dataBits - 4 - 8 - 4) / 8);
}

function qrVersionForText(text) {
  const byteLength = Buffer.byteLength(text, "utf8");
  for (let version = 1; version < QR_ECC_M_TABLE.length; version += 1) {
    if (byteLength <= qrByteCapacity(version)) return version;
  }
  return 0;
}

function appendQrBits(bits, value, length) {
  for (let i = length - 1; i >= 0; i -= 1) {
    bits.push(((value >>> i) & 1) === 1);
  }
}

function qrDataCodewords(text, version) {
  const bytes = [...Buffer.from(text, "utf8")];
  const table = QR_ECC_M_TABLE[version];
  const bits = [];
  appendQrBits(bits, 0b0100, 4);
  appendQrBits(bits, bytes.length, 8);
  bytes.forEach((byte) => appendQrBits(bits, byte, 8));
  const capacityBits = table.dataCodewords * 8;
  appendQrBits(bits, 0, Math.min(4, capacityBits - bits.length));
  while (bits.length % 8 !== 0) bits.push(false);
  const codewords = [];
  for (let i = 0; i < bits.length; i += 8) {
    let value = 0;
    for (let bit = 0; bit < 8; bit += 1) {
      value = (value << 1) | (bits[i + bit] ? 1 : 0);
    }
    codewords.push(value);
  }
  for (let pad = 0; codewords.length < table.dataCodewords; pad += 1) {
    codewords.push(pad % 2 === 0 ? 0xec : 0x11);
  }
  return codewords;
}

function qrGfMultiply(x, y) {
  let z = 0;
  for (let i = 7; i >= 0; i -= 1) {
    z = (z << 1) ^ ((z >>> 7) * 0x11d);
    z ^= ((y >>> i) & 1) * x;
  }
  return z;
}

function qrReedSolomonDivisor(degree) {
  const result = Array(degree - 1).fill(0);
  result.push(1);
  let root = 1;
  for (let i = 0; i < degree; i += 1) {
    for (let j = 0; j < result.length; j += 1) {
      result[j] = qrGfMultiply(result[j], root);
      if (j + 1 < result.length) result[j] ^= result[j + 1];
    }
    root = qrGfMultiply(root, 0x02);
  }
  return result;
}

function qrReedSolomonRemainder(data, divisor) {
  const result = Array(divisor.length).fill(0);
  data.forEach((byte) => {
    const factor = byte ^ result.shift();
    result.push(0);
    divisor.forEach((coefficient, index) => {
      result[index] ^= qrGfMultiply(coefficient, factor);
    });
  });
  return result;
}

function qrCodewords(text, version) {
  const table = QR_ECC_M_TABLE[version];
  const data = qrDataCodewords(text, version);
  const divisor = qrReedSolomonDivisor(table.ecCodewords);
  const blocks = [];
  let offset = 0;
  table.blocks.forEach((length) => {
    const blockData = data.slice(offset, offset + length);
    offset += length;
    blocks.push({
      data: blockData,
      ec: qrReedSolomonRemainder(blockData, divisor),
    });
  });
  const codewords = [];
  const maxDataLength = Math.max(...blocks.map((block) => block.data.length));
  for (let i = 0; i < maxDataLength; i += 1) {
    blocks.forEach((block) => {
      if (i < block.data.length) codewords.push(block.data[i]);
    });
  }
  for (let i = 0; i < table.ecCodewords; i += 1) {
    blocks.forEach((block) => codewords.push(block.ec[i]));
  }
  return codewords;
}

function qrBlankMatrix(size) {
  return {
    modules: Array.from({ length: size }, () => Array(size).fill(false)),
    reserved: Array.from({ length: size }, () => Array(size).fill(false)),
  };
}

function setQrModule(matrix, row, col, dark, reserved = true) {
  if (row < 0 || col < 0 || row >= matrix.modules.length || col >= matrix.modules.length) return;
  matrix.modules[row][col] = Boolean(dark);
  if (reserved) matrix.reserved[row][col] = true;
}

function drawQrFinder(matrix, row, col) {
  for (let y = -1; y <= 7; y += 1) {
    for (let x = -1; x <= 7; x += 1) {
      const r = row + y;
      const c = col + x;
      const dark = x >= 0 && x <= 6 && y >= 0 && y <= 6
        && (x === 0 || x === 6 || y === 0 || y === 6 || (x >= 2 && x <= 4 && y >= 2 && y <= 4));
      setQrModule(matrix, r, c, dark);
    }
  }
}

function drawQrAlignment(matrix, row, col) {
  for (let y = -2; y <= 2; y += 1) {
    for (let x = -2; x <= 2; x += 1) {
      setQrModule(matrix, row + y, col + x, Math.max(Math.abs(x), Math.abs(y)) !== 1);
    }
  }
}

function drawQrFunctionPatterns(matrix, version) {
  const size = matrix.modules.length;
  drawQrFinder(matrix, 0, 0);
  drawQrFinder(matrix, 0, size - 7);
  drawQrFinder(matrix, size - 7, 0);
  for (let i = 0; i < size; i += 1) {
    if (!matrix.reserved[6][i]) setQrModule(matrix, 6, i, i % 2 === 0);
    if (!matrix.reserved[i][6]) setQrModule(matrix, i, 6, i % 2 === 0);
  }
  QR_ALIGNMENT_CENTERS[version].forEach((row) => {
    QR_ALIGNMENT_CENTERS[version].forEach((col) => {
      if (!matrix.reserved[row][col]) drawQrAlignment(matrix, row, col);
    });
  });
  setQrModule(matrix, size - 8, 8, true);
}

function qrFormatBit(index) {
  return ((QR_FORMAT_M_MASK_0 >>> index) & 1) === 1;
}

function drawQrFormatBits(matrix) {
  const size = matrix.modules.length;
  for (let i = 0; i <= 5; i += 1) setQrModule(matrix, 8, i, qrFormatBit(i));
  setQrModule(matrix, 8, 7, qrFormatBit(6));
  setQrModule(matrix, 8, 8, qrFormatBit(7));
  setQrModule(matrix, 7, 8, qrFormatBit(8));
  for (let i = 9; i < 15; i += 1) setQrModule(matrix, 14 - i, 8, qrFormatBit(i));
  for (let i = 0; i < 8; i += 1) setQrModule(matrix, size - 1 - i, 8, qrFormatBit(i));
  for (let i = 8; i < 15; i += 1) setQrModule(matrix, 8, size - 15 + i, qrFormatBit(i));
}

function drawQrCodewords(matrix, codewords) {
  const size = matrix.modules.length;
  const bits = codewords.flatMap((codeword) =>
    Array.from({ length: 8 }, (_, index) => ((codeword >>> (7 - index)) & 1) === 1)
  );
  let bitIndex = 0;
  let upward = true;
  for (let col = size - 1; col >= 1; col -= 2) {
    if (col === 6) col -= 1;
    for (let rowOffset = 0; rowOffset < size; rowOffset += 1) {
      const row = upward ? size - 1 - rowOffset : rowOffset;
      for (let c = col; c >= col - 1; c -= 1) {
        if (matrix.reserved[row][c]) continue;
        const rawBit = bitIndex < bits.length ? bits[bitIndex] : false;
        const masked = rawBit !== ((row + c) % 2 === 0);
        setQrModule(matrix, row, c, masked, false);
        bitIndex += 1;
      }
    }
    upward = !upward;
  }
}

function qrXmlEscape(value) {
  return String(value).replace(/[&<>"]/g, (char) => {
    if (char === "&") return "&amp;";
    if (char === "<") return "&lt;";
    if (char === ">") return "&gt;";
    return "&quot;";
  });
}

function buildInstallQrSvg(text) {
  const version = qrVersionForText(text);
  if (!version) {
    const escapedText = qrXmlEscape(text);
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 220" role="img" aria-label="Install URL too long for QR"><rect width="640" height="220" fill="#fff7ed"/><text x="24" y="48" font-family="monospace" font-size="20" fill="#92400e">Install URL is too long for the built-in QR.</text><text x="24" y="92" font-family="monospace" font-size="16" fill="#1f2937">${escapedText}</text></svg>`;
  }
  const size = 21 + 4 * (version - 1);
  const quiet = 4;
  const matrix = qrBlankMatrix(size);
  drawQrFunctionPatterns(matrix, version);
  drawQrFormatBits(matrix);
  drawQrCodewords(matrix, qrCodewords(text, version));
  const darkModules = [];
  matrix.modules.forEach((row, y) => {
    row.forEach((dark, x) => {
      if (dark) darkModules.push(`<rect x="${x + quiet}" y="${y + quiet}" width="1" height="1"/>`);
    });
  });
  const viewSize = size + quiet * 2;
  const label = qrXmlEscape(`Travel Planner iPhone install QR for ${text}`);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${viewSize} ${viewSize}" shape-rendering="crispEdges" role="img" aria-label="${label}"><rect width="100%" height="100%" fill="#ffffff"/><g fill="#0f172a">${darkModules.join("")}</g></svg>`;
}

function buildInstallInfo(req) {
  const forwardedProto = (req.get("x-forwarded-proto") || "").split(",")[0].trim();
  const protocol = forwardedProto || req.protocol;
  const currentOrigin = `${protocol}://${req.get("host")}`;
  const isHttps = protocol === "https";
  const installPath = "/install.html";
  const shortInstallPath = "/i";
  const lanOrigins = localNetworkOrigins();
  const currentInstallUrl = `${currentOrigin}${installPath}`;
  const currentShortInstallUrl = `${currentOrigin}${shortInstallPath}`;
  const lanInstallUrls = lanOrigins.map((origin) => `${origin}${installPath}`);
  const lanShortInstallUrls = lanOrigins.map((origin) => `${origin}${shortInstallPath}`);
  const configuredPublicOrigin = normalizePublicOrigin(process.env.TRAVEL_PLANNER_PUBLIC_ORIGIN);
  const configuredInstallUrl = configuredPublicOrigin ? `${configuredPublicOrigin}${installPath}` : "";
  const configuredShortInstallUrl = configuredPublicOrigin ? `${configuredPublicOrigin}${shortInstallPath}` : "";
  const configuredPublicOriginIsHttps = configuredPublicOrigin.startsWith("https://");
  const recommendedInstallUrl = configuredPublicOriginIsHttps
    ? configuredInstallUrl
    : isLocalhostName(req.hostname) && lanInstallUrls[0]
      ? lanInstallUrls[0]
      : currentInstallUrl;
  const recommendedShortInstallUrl = configuredPublicOriginIsHttps
    ? configuredShortInstallUrl
    : isLocalhostName(req.hostname) && lanShortInstallUrls[0]
      ? lanShortInstallUrls[0]
      : currentShortInstallUrl;
  const proofSaveUrl = new URL(recommendedInstallUrl);
  const proofSaveHash = "#iosInstallProofSaveButton";
  const proofSaveTargetId = "iosInstallProofSaveButton";
  proofSaveUrl.hash = proofSaveHash;
  const installSessionUrl = new URL(recommendedInstallUrl);
  installSessionUrl.pathname = "/api/ios-install-session.txt";
  installSessionUrl.search = "";
  installSessionUrl.hash = "";
  const installQuickstartUrl = new URL(recommendedInstallUrl);
  installQuickstartUrl.pathname = "/api/ios-install-quickstart.txt";
  installQuickstartUrl.search = "";
  installQuickstartUrl.hash = "";
  const recommendedUrlIsHttps = recommendedInstallUrl.startsWith("https://");
  const recommendedUrlSource = configuredPublicOriginIsHttps
    ? "configured-public-https"
    : isLocalhostName(req.hostname) && lanInstallUrls[0]
      ? "same-wifi-lan"
      : isHttps
        ? "current-https-origin"
        : "current-origin";
  const sameWifiRequired = recommendedUrlSource === "same-wifi-lan";
  const installReadinessSummary = {
    recommendedUrlSource,
    recommendedUrlIsHttps,
    sameWifiRequired,
    safariRequired: true,
    summary: recommendedUrlIsHttps
      ? "iPhone Safari에서 recommendedInstallUrl을 열고 홈 화면에 추가하세요."
      : sameWifiRequired
        ? "iPhone과 Mac이 같은 Wi-Fi에 있을 때 recommendedInstallUrl을 Safari에서 여세요. 실사용은 HTTPS 배포 주소를 권장합니다."
        : "현재 추천 URL은 HTTPS가 아닙니다. iPhone 실사용 설치 전 HTTPS 배포 주소를 준비하는 것을 권장합니다.",
  };

  return {
    currentOrigin,
    installPath,
    shortInstallPath,
    installQrSvgUrl: `${currentOrigin}/api/install-qr.svg`,
    installQrTargetUrl: recommendedInstallUrl,
    installRunbookUrl: `${currentOrigin}/api/ios-install-runbook.txt`,
    installRunbookJsonUrl: `${currentOrigin}/api/ios-install-runbook`,
    installQuickstartUrl: installQuickstartUrl.toString(),
    installSessionUrl: installSessionUrl.toString(),
    installSessionQrUrl: `${currentOrigin}/api/ios-install-session-qr.svg`,
    installUrl: currentInstallUrl,
    shortInstallUrl: currentShortInstallUrl,
    recommendedInstallUrl,
    recommendedShortInstallUrl,
    proofSaveHash,
    proofSaveTargetId,
    proofSaveUrl: proofSaveUrl.toString(),
    installReadinessSummary,
    protectedRecommendedInstallUrlTemplate: `${recommendedInstallUrl}?travelAccessKey=YOUR_TRAVEL_ACCESS_KEY`,
    protectedRecommendedShortInstallUrlTemplate: `${recommendedShortInstallUrl}?travelAccessKey=YOUR_TRAVEL_ACCESS_KEY`,
    protectedInstallAccessKeyHandling: {
      placeholder: "YOUR_TRAVEL_ACCESS_KEY",
      localCompositionOnly: true,
      storesEnteredKey: false,
      sendsEnteredKeyToServer: false,
      clearsTemporaryInputAfterCopy: true,
    },
    evidenceCommands: {
      base: "npm run ios:install:evidence",
      nextStep: "npm run ios:install:next",
      beforePhone: "npm run ios:install:evidence:before-phone",
      beforePhoneFinal: "npm run ios:install:evidence:before-phone:final",
      beforePhoneFinalThenNext: "npm run ios:install:evidence:before-phone:final:next",
      handoffEvidence: "npm run ios:install:handoff:evidence",
      sessionEvidence: "npm run ios:install:session:evidence",
      handoffSessionEvidence: "npm run ios:install:handoff-session:evidence",
      afterPhone: "npm run ios:install:evidence:after-phone",
      all: "npm run ios:install:evidence:all",
      allFinal: "npm run ios:install:evidence:all:final",
      afterPhoneThenAll: "npm run ios:install:evidence:after-phone && npm run ios:install:evidence:all",
      afterPhoneThenAllFinal: "npm run ios:install:evidence:after-phone:final",
      preinstall: "npm run ios:install:evidence:preinstall",
      postinstall: "npm run ios:install:evidence:postinstall",
      nextStepTerminal: "test -d webapp && cd webapp; npm run ios:install:next",
      beforePhoneTerminal: "test -d webapp && cd webapp; npm run ios:install:evidence:before-phone",
      beforePhoneFinalTerminal: "test -d webapp && cd webapp; npm run ios:install:evidence:before-phone:final",
      beforePhoneFinalThenNextTerminal: "test -d webapp && cd webapp; npm run ios:install:evidence:before-phone:final:next",
      handoffEvidenceTerminal: "test -d webapp && cd webapp; npm run ios:install:handoff:evidence",
      sessionEvidenceTerminal: "test -d webapp && cd webapp; npm run ios:install:session:evidence",
      handoffSessionEvidenceTerminal: "test -d webapp && cd webapp; npm run ios:install:handoff-session:evidence",
      afterPhoneTerminal: "test -d webapp && cd webapp; npm run ios:install:evidence:after-phone",
      allTerminal: "test -d webapp && cd webapp; npm run ios:install:evidence:all",
      allFinalTerminal: "test -d webapp && cd webapp; npm run ios:install:evidence:all:final",
      afterPhoneThenAllTerminal: "test -d webapp && cd webapp; npm run ios:install:evidence:after-phone && npm run ios:install:evidence:all",
      afterPhoneThenAllFinalTerminal: "test -d webapp && cd webapp; npm run ios:install:evidence:after-phone:final",
      preinstallTerminal: "test -d webapp && cd webapp; npm run ios:install:evidence:preinstall",
      postinstallTerminal: "test -d webapp && cd webapp; npm run ios:install:evidence:postinstall",
      strictPreInstall: "npm run ios:install:evidence:strict",
      proofPostInstall: "npm run ios:install:evidence:proof",
    },
    maintenanceCommands: {
      maintenance: "npm run ios:install:maintenance",
      maintenanceTerminal: "test -d webapp && cd webapp; npm run ios:install:maintenance",
      schemaSyncSource: "npm run ios:install:schemas:sync-source",
      schemaSyncSourceTerminal: "test -d webapp && cd webapp; npm run ios:install:schemas:sync-source",
    },
    nextActionContract: {
      phoneFirstField: "phoneFirst",
      nextCommandLabelField: "nextCommandLabel",
      nextCommandPrerequisiteField: "nextCommandPrerequisite",
      finalGateCommand: "npm run ios:install:evidence:after-phone:final",
      finalGateTerminalCommand: "test -d webapp && cd webapp; npm run ios:install:evidence:after-phone:final",
      finalGatePrerequisite: "Run only after Add to Home Screen, Travel icon launch, and install proof save.",
    },
    configuredPublicOrigin,
    configuredInstallUrl,
    configuredShortInstallUrl,
    configuredPublicOriginIsHttps,
    isHttps,
    isLocalhost: isLocalhostName(req.hostname),
    lanOrigins,
    lanInstallUrls,
    lanShortInstallUrls,
    iosSteps: [
      "iPhone Safari에서 installUrl 열기",
      "공유 버튼 선택",
      "홈 화면에 추가 선택",
      "추가 선택",
    ],
    deploymentRecommendation: configuredPublicOriginIsHttps
      ? "TRAVEL_PLANNER_PUBLIC_ORIGIN HTTPS 주소를 iPhone 설치 주소로 우선 사용합니다."
      : configuredPublicOrigin
        ? "TRAVEL_PLANNER_PUBLIC_ORIGIN이 설정됐지만 HTTPS가 아닙니다. iPhone 실사용 설치에는 HTTPS 배포 주소를 권장합니다."
    : isHttps
      ? "현재 주소는 HTTPS라 iPhone 홈 화면 설치와 service worker 동작에 적합합니다."
      : "iPhone에서 계속 쓰려면 HTTPS 배포 주소를 권장합니다. 로컬 LAN 주소는 같은 Wi-Fi 설치 확인용으로 사용하세요.",
    note: isHttps
      ? "HTTPS 배포 URL이면 service worker와 홈 화면 설치 경험이 가장 안정적입니다."
      : "로컬 HTTP 주소는 홈 화면 추가는 가능하지만 service worker와 오프라인 동작이 제한될 수 있습니다. 실제 사용은 HTTPS 배포를 권장합니다.",
  };
}

