function buildIosInstallRunbookText(runbook) {
  const lines = [
    "# Travel Planner iPhone install runbook",
    "",
    `deploymentMode=${runbook.deploymentMode}`,
    `recommendedInstallUrl=${runbook.recommendedInstallUrl}`,
    `recommendedShortInstallUrl=${runbook.recommendedShortInstallUrl}`,
    `protectedRecommendedInstallUrlTemplate=${runbook.protectedRecommendedInstallUrlTemplate}`,
    `protectedRecommendedShortInstallUrlTemplate=${runbook.protectedRecommendedShortInstallUrlTemplate}`,
    `protectedInstallAccessKeyPlaceholder=${runbook.protectedInstallAccessKeyHandling.placeholder}`,
    `protectedInstallAccessKeyLocalCompositionOnly=${runbook.protectedInstallAccessKeyHandling.localCompositionOnly ? "true" : "false"}`,
    `protectedInstallAccessKeyStoresEnteredKey=${runbook.protectedInstallAccessKeyHandling.storesEnteredKey ? "true" : "false"}`,
    `protectedInstallAccessKeySendsEnteredKeyToServer=${runbook.protectedInstallAccessKeyHandling.sendsEnteredKeyToServer ? "true" : "false"}`,
    `protectedInstallAccessKeyClearsTemporaryInputAfterCopy=${runbook.protectedInstallAccessKeyHandling.clearsTemporaryInputAfterCopy ? "true" : "false"}`,
    `installReadinessSource=${runbook.installReadinessSummary.recommendedUrlSource}`,
    `installReadinessHttps=${runbook.installReadinessSummary.recommendedUrlIsHttps ? "true" : "false"}`,
    `installReadinessSameWifiRequired=${runbook.installReadinessSummary.sameWifiRequired ? "true" : "false"}`,
    `installReadinessSafariRequired=${runbook.installReadinessSummary.safariRequired ? "true" : "false"}`,
    `installReadinessSummary=${runbook.installReadinessSummary.summary}`,
    `nextStepUrl=${runbook.nextStepUrl}`,
    `nextStepTextUrl=${runbook.nextStepTextUrl}`,
    `proofSaveHash=${runbook.proofSaveHash}`,
    `proofSaveTargetId=${runbook.proofSaveTargetId}`,
    `proofSaveUrl=${runbook.proofSaveUrl}`,
    `installInfoUrl=${runbook.installInfoUrl}`,
    `handoffNoteUrl=${runbook.handoffNoteUrl}`,
    `installSessionUrl=${runbook.installSessionUrl}`,
    `nextActionScanUrl=${runbook.nextActionScanUrl}`,
    `nextActionScanLongUrl=${runbook.nextActionScanLongUrl}`,
    `nextActionTextUrl=${runbook.nextActionTextUrl}`,
    `nextActionQrUrl=${runbook.nextActionQrUrl}`,
    `postInstallAppHomeUrl=${runbook.postInstallAppHomeUrl}`,
    `postInstallNewPlanUrl=${runbook.postInstallNewPlanUrl}`,
    `appShellRecoveryUrl=${runbook.appShellRecoveryUrl}`,
    `appShellRecoveryTrigger=${runbook.appShellRecovery.triggerField}=true`,
    ...runbook.appShellRecovery.sequence.map((step) => `appShellRecoveryStep=${step}`),
    "appShellRecovery=If launch proof reports appShellUpdateNeeded=true, open appShellRecoveryUrl on the installed iPhone app, tap app update check, apply the shell update, save proof again, then run the final Mac gate.",
    `completionMacEvidenceSequenceCommand=${runbook.completionMacEvidenceSequenceCommand}`,
    `completionMacEvidenceSequenceTerminalCommand=${runbook.completionMacEvidenceSequenceTerminalCommand}`,
    `iosEvidenceFreshnessStaleAfterHours=${runbook.iosEvidenceFreshness.staleAfterHours}`,
    `iosEvidenceFreshnessStaleAfterEnvVar=${runbook.iosEvidenceFreshness.staleAfterEnvVar}`,
    `iosInstallMaintenanceCommand=${runbook.maintenanceCommands.maintenance}`,
    `iosInstallMaintenanceTerminalCommand=${runbook.maintenanceCommands.maintenanceTerminal}`,
    `iosInstallSchemaSyncSourceCommand=${runbook.maintenanceCommands.schemaSyncSource}`,
    `iosInstallSchemaSyncSourceTerminalCommand=${runbook.maintenanceCommands.schemaSyncSourceTerminal}`,
    `proofSummaryUrl=${runbook.proofSummaryUrl}`,
    `nextActionPhoneFirstField=${runbook.nextActionContract.phoneFirstField}`,
    `nextActionFinalGateCommand=${runbook.nextActionContract.finalGateCommand}`,
    `nextActionFinalGateTerminalCommand=${runbook.nextActionContract.finalGateTerminalCommand}`,
  ];
  if (!runbook.publicOriginIsHttps) {
    lines.push(
      "",
      "# Note: stable iPhone use should use TRAVEL_PLANNER_PUBLIC_ORIGIN with an HTTPS URL.",
      "# Local/LAN URLs are useful for same-Wi-Fi rehearsal only.",
    );
  }
  for (const phase of runbook.phases) {
    lines.push("", `## ${phase.title}`, phase.goal);
    for (const command of phase.commands) lines.push(`command=${command}`);
    for (const command of phase.terminalCommands || []) lines.push(`terminalCommand=${command}`);
    for (const step of phase.phoneSteps) lines.push(`phoneStep=${step}`);
  }
  lines.push("", "# Ready signal:");
  lines.push("# Treat the install as complete only after post-install evidence passes with saved iPhone Home Screen launch proof.");
  return `${lines.join("\n")}\n`;
}

function buildIosInstallSession(info, next) {
  const reports = next.reports || {};
  const launchProofAppModeState = reports.summaryCheck?.appModeState || reports.launchProofCheck?.appModeState || "";
  const launchProofAppModeReady = reports.summaryCheck?.launchProofAppModeReady === true || launchProofAppModeState === "standalone";
  const launchProofAppShell = reports.launchProofCheck?.appShell || reports.summaryCheck?.appShell || "";
  const launchProofServerShell = reports.launchProofCheck?.serverShell || reports.summaryCheck?.serverShell || "";
  const launchProofAppShellUpdateNeeded = reports.launchProofCheck?.appShellUpdateNeeded === true || reports.summaryCheck?.appShellUpdateNeeded === true;
  const installSessionUrl = new URL(info.recommendedInstallUrl);
  installSessionUrl.pathname = "/api/ios-install-session.txt";
  installSessionUrl.search = "";
  installSessionUrl.hash = "";
  return {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    status: next.action === "complete" ? "complete" : "in-progress",
    install: {
      url: info.recommendedInstallUrl,
      shortUrl: info.recommendedShortInstallUrl,
      qrUrl: info.installQrSvgUrl,
      sessionUrl: installSessionUrl.toString(),
      sessionQrUrl: `${info.currentOrigin}/api/ios-install-session-qr.svg`,
      nextActionScanUrl: iosInstallCompletionStatusUrl(info, "/ios-next"),
      nextActionScanLongUrl: iosInstallCompletionStatusUrl(info, "/ios-install-next-action-scan"),
      nextActionTextUrl: iosInstallCompletionStatusUrl(info, "/api/ios-install-next-action.txt"),
      nextActionQrUrl: iosInstallCompletionStatusUrl(info, "/api/ios-install-next-action-qr.svg"),
      proofSaveHash: info.proofSaveHash,
      proofSaveTargetId: info.proofSaveTargetId,
      postInstallAppHomeUrl: iosInstallCompletionStatusUrl(info, "/#iosHomeDock"),
      postInstallNewPlanUrl: iosInstallCompletionStatusUrl(info, "/#planForm"),
      proofSaveUrl: info.proofSaveUrl,
      appShellRecoveryUrl: iosInstallCompletionStatusUrl(info, "/#iosHomeDockShellRecovery"),
      appShellRecovery: {
        url: iosInstallCompletionStatusUrl(info, "/#iosHomeDockShellRecovery"),
        triggerField: "appShellUpdateNeeded",
        triggerValue: true,
        sequence: [
          "Open appShellRecoveryUrl on the installed iPhone app.",
          "Tap app update check in the Home Screen dock.",
          "Apply the shell update if the new-version prompt appears.",
          "Save Home Screen proof again.",
          "Run the final Mac gate command.",
        ],
      },
      handoffNoteUrl: `${info.currentOrigin}/api/ios-install-handoff.txt`,
      runbookUrl: `${info.currentOrigin}/api/ios-install-runbook.txt`,
      installInfoUrl: `${info.currentOrigin}/api/install-info.txt`,
    },
    nextAction: {
      action: next.action || "",
      title: next.title || "",
      phoneFirst: next.phoneFirst === true,
      phoneStep: next.phoneStep || "",
      command: next.nextCommand || "",
      terminalCommand: next.nextTerminalCommand || "",
      commandLabel: next.nextCommandLabel || "",
      prerequisite: next.nextCommandPrerequisite || "",
    },
    commands: {
      beforePhone: info.evidenceCommands.beforePhone,
      beforePhoneFinal: info.evidenceCommands.beforePhoneFinal,
      beforePhoneFinalThenNext: info.evidenceCommands.beforePhoneFinalThenNext,
      handoffEvidence: info.evidenceCommands.handoffEvidence,
      sessionEvidence: info.evidenceCommands.sessionEvidence,
      handoffSessionEvidence: info.evidenceCommands.handoffSessionEvidence,
      afterPhoneThenAll: info.evidenceCommands.afterPhoneThenAll,
      afterPhoneThenAllFinal: info.evidenceCommands.afterPhoneThenAllFinal,
      beforePhoneTerminal: info.evidenceCommands.beforePhoneTerminal,
      beforePhoneFinalTerminal: info.evidenceCommands.beforePhoneFinalTerminal,
      beforePhoneFinalThenNextTerminal: info.evidenceCommands.beforePhoneFinalThenNextTerminal,
      handoffEvidenceTerminal: info.evidenceCommands.handoffEvidenceTerminal,
      sessionEvidenceTerminal: info.evidenceCommands.sessionEvidenceTerminal,
      handoffSessionEvidenceTerminal: info.evidenceCommands.handoffSessionEvidenceTerminal,
      afterPhoneThenAllTerminal: info.evidenceCommands.afterPhoneThenAllTerminal,
      afterPhoneThenAllFinalTerminal: info.evidenceCommands.afterPhoneThenAllFinalTerminal,
    },
    evidence: {
      runbookReady: reports.runbook?.ready === true,
      preInstallReady: reports.strict?.ready === true,
      launchProofReady: reports.launchProofCheck?.ready === true,
      launchProofAppModeReady,
      launchProofAppModeState,
      launchProofAppModeTitle: reports.launchProofCheck?.appModeTitle || reports.summaryCheck?.appModeTitle || "",
      launchProofDisplayMode: reports.launchProofCheck?.displayMode || reports.summaryCheck?.displayMode || "",
      launchProofAppShell,
      launchProofServerShell,
      launchProofAppShellUpdateNeeded,
      postInstallReady: reports.proof?.ready === true,
      finalGateReady: reports.summaryCheck?.ready === true,
      reports,
    },
    iosEvidenceFreshness: {
      ...IOS_EVIDENCE_FRESHNESS_POLICY,
    },
    maintenanceCommands: {
      ...info.maintenanceCommands,
    },
    completionRule: "Complete only after iPhone Home Screen launch proof is saved and the Mac final gate passes.",
  };
}

