app.get("/api/ios-install-session-qr.svg", (req, res) => {
  const info = buildInstallInfo(req);
  const targetUrl = new URL(info.recommendedInstallUrl);
  targetUrl.pathname = "/api/ios-install-session.txt";
  targetUrl.search = "";
  targetUrl.hash = "";
  let qrTargetUrl = targetUrl.toString();
  const requestedTarget = Array.isArray(req.query.target) ? req.query.target[0] : req.query.target;
  if (typeof requestedTarget === "string" && requestedTarget) {
    try {
      const target = new URL(requestedTarget);
      const allowedOrigins = new Set([info.currentOrigin, info.configuredPublicOrigin, ...(info.lanOrigins || [])].filter(Boolean));
      if (target.pathname === "/api/ios-install-session.txt" && allowedOrigins.has(target.origin)) {
        target.search = "";
        target.hash = "";
        qrTargetUrl = target.toString();
      }
    } catch {
      qrTargetUrl = targetUrl.toString();
    }
  }
  res.type("image/svg+xml").send(buildInstallQrSvg(qrTargetUrl));
});

app.get("/api/install-qr.svg", (req, res) => {
  const info = buildInstallInfo(req);
  let qrTargetUrl = info.recommendedInstallUrl;
  const requestedTarget = Array.isArray(req.query.target) ? req.query.target[0] : req.query.target;
  if (typeof requestedTarget === "string" && requestedTarget) {
    try {
      const target = new URL(requestedTarget);
      const allowedOrigins = new Set([info.currentOrigin, info.configuredPublicOrigin, ...(info.lanOrigins || [])].filter(Boolean));
      if ((target.pathname === "/install" || target.pathname === "/install.html" || target.pathname === "/i") && allowedOrigins.has(target.origin)) {
        qrTargetUrl = target.toString();
      }
    } catch {
      qrTargetUrl = info.recommendedInstallUrl;
    }
  }
  res
    .type("image/svg+xml")
    .set("Cache-Control", "no-store")
    .send(buildInstallQrSvg(qrTargetUrl));
});

