function startupInstallUrls() {
  const localOrigin = `http://localhost:${PORT}`;
  const lanShortUrls = localNetworkOrigins().map((origin) => `${origin}/i`);
  const lanNextActionScanUrls = localNetworkOrigins().map((origin) => `${origin}/ios-next`);
  const publicOrigin = normalizePublicOrigin(process.env.TRAVEL_PLANNER_PUBLIC_ORIGIN);
  const publicShortUrl = publicOrigin ? `${publicOrigin}/i` : "";
  const publicNextActionScanUrl = publicOrigin ? `${publicOrigin}/ios-next` : "";
  return {
    localOrigin,
    localShortUrl: `${localOrigin}/i`,
    localNextActionScanUrl: `${localOrigin}/ios-next`,
    lanShortUrls,
    lanNextActionScanUrls,
    publicShortUrl,
    publicNextActionScanUrl,
  };
}

app.listen(PORT, () => {
  const urls = startupInstallUrls();
  console.log(`Travel planner web app is running on ${urls.localOrigin}`);
  console.log(`iPhone install short URL: ${urls.publicShortUrl || urls.lanShortUrls[0] || urls.localShortUrl}`);
  console.log(`iPhone next-action scan board: ${urls.publicNextActionScanUrl || urls.lanNextActionScanUrls[0] || urls.localNextActionScanUrl}`);
  if (urls.lanShortUrls.length) {
    console.log(`Same-Wi-Fi iPhone candidates: ${urls.lanShortUrls.join(", ")}`);
  }
  if (urls.lanNextActionScanUrls.length) {
    console.log(`Same-Wi-Fi next-action scan boards: ${urls.lanNextActionScanUrls.join(", ")}`);
  }
  if (urls.publicShortUrl) {
    console.log(`Public iPhone install URL: ${urls.publicShortUrl}`);
  }
  if (urls.publicNextActionScanUrl) {
    console.log(`Public next-action scan board: ${urls.publicNextActionScanUrl}`);
  }
  console.log(`Install handoff note: ${urls.localOrigin}/api/ios-install-handoff.txt`);
});
